          const placeBtn = page.getByRole('button', { name: /の下に置く/ }).first();
          if (await placeBtn.count() && await placeBtn.isVisible().catch(() => false)) { await placeBtn.click().catch(() => {}); did = 'btn:の下に置く'; }
