      const ok = leaveSubHas(st?.guest?.fieldSigni, LEAVE_SUB_VICTIM)
        && !leaveSubHas(st?.guest?.fieldSigni, LEAVE_SUB_SACRIFICE)
        && (st?.guest?.energyCards ?? []).includes(LEAVE_SUB_SACRIFICE)
        && st?.guest?.leaveSubstituteChoices == null;
      return ok
