  title: 'V-19① WX16-Re18：doPhaseAdvance手札上限内経路で実装上の1枚をルリグデッキへ返却',
  spec: v19ArtsSpec(false),
  drive: (page, H) => driveV19ReturnAtTurnEnd(page, H, { source: V19_ARTS, resona: V19_ARTS_RESONA, withDiscard: false }),
