// ── §7 V-65（続き544・O-38「相手シグニ【自】の支払えば通る回避」）──
// `blocked_actions` へ `PAY_GATE_OPP_SIGNI_AUTO:無`（`blockAction.ts` の signiAutoPayGateMarkers）を
// guest 側へ直接注入する（SPDi43-01 を実際に撃つ手順を省略＝ゲートが「宣言済みで有効」な状態を作る）。
// host の WXK04-028（【自】《ターン１回》：エナチャージをしたとき、エナチャージ１）を
// WX01-049（【起】《ダウン》：デッキ最上をエナへ）で発火させ、
// (a) 窓が実際に出る（「支払う（コスト: 《無》）」／「支払わない」の2択）
// (b) 支払えば本体が通り、host.energy が2枚（手動ぶん+ボーナスぶん）になる
// (c) 支払わなければ何も起きず host.energy は1枚（手動ぶんのみ）のまま
// を見る。⚠旧実装はこの窓が一度も出ずに丸ごと止めていた（`BLOCK_OPP_SIGNI_AUTO` で無条件ブロック）。
const v65PayGateSpec = {
  hostSet: {
    'field.lrig': ['WD01-001#9980'], 'field.signi': [['WXK04-028#9981'], ['WX01-049#9982'], null],
    'field.check': null, 'field.signi_down': [false, false, false],
    // ⚠deckは2枚以下だと2回のエナチャージ（WX01-049分＋ボーナス分）で0枚になり、
    //   「デッキ0枚→リフレッシュ」がtrashの中身をdeckへ戻してしまい判定が汚染される（続き563実測）。
    //   余裕を持って5枚積む。
    'energy': ['WD01-014#9983'], 'deck': ['WD01-013#9984', 'WD01-013#9985', 'WD01-013#9986', 'WD01-013#9987', 'WD01-013#9988'],
    'hand': [], 'actions_done': [],
  },
  guestSet: {
    'field.lrig': ['WD01-001#9990'], 'field.signi': [null, null, null], 'field.check': null,
    'blocked_actions': ['PAY_GATE_OPP_SIGNI_AUTO:無'],
    'hand': [], 'energy': [],
  },
  top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
};

async function driveV65PayGate(page, H, payChoice) {
  await H.ensureMain();
  await page.waitForTimeout(600);
  await H.clickTestId('my-signi-zone-1').catch(() => {});
  await page.waitForTimeout(500);
  const downBtn = page.getByRole('button', { name: '【起】ダウン', exact: false }).first();
  if (await downBtn.count() && await downBtn.isVisible().catch(() => false)) {
    await downBtn.click({ timeout: 3000 }).catch(() => {});
  }
  await page.waitForTimeout(400);
  await H.clickBtn('発動', { exact: true });
  let fin = null;
  let windowSeen = false;
  let energySelected = false;
  for (let s = 0; s < 10; s++) {
    await page.waitForTimeout(400);
    const skipBtn = page.getByTestId('optcost-skip').first();
    const energyCard0 = page.getByTestId('optcost-energy-0').first();
    const payBtn = page.getByTestId('optcost-pay').first();
    const skipVisible = await skipBtn.count() && await skipBtn.isVisible().catch(() => false);
    const energyVisible = await energyCard0.count() && await energyCard0.isVisible().catch(() => false);
    if (skipVisible || energyVisible) windowSeen = true;
    let did = null;
    if (!payChoice && skipVisible) { await skipBtn.click({ timeout: 3000 }).catch(() => {}); did = 'btn:支払わない'; }
    else if (payChoice && energyVisible && !energySelected) {
      await energyCard0.click({ timeout: 3000 }).catch(() => {}); did = 'click:optcost-energy-0'; energySelected = true;
    } else if (payChoice && energySelected) {
      const payEnabled = await payBtn.count() && await payBtn.isEnabled().catch(() => false);
      if (payEnabled) { await payBtn.click({ timeout: 3000 }).catch(() => {}); did = 'btn:optcost-pay'; }
    }
    if (!did) did = await H.stdStep();
    fin = await H.queryState();
    H.log(`  v65paygate[${s}] did=${did} windowSeen=${windowSeen} pendingEffect=${fin?.pendingEffect} energy=${fin?.host?.energy} deck=${fin?.host?.deck} trash=${JSON.stringify(fin?.host?.trashCards)} logTail末尾=${JSON.stringify((fin?.logTail ?? []).slice(-2))}`);
  }
  return { fin, windowSeen };
}

scenarios.v65PayGateWindowAppearsAndPayingFires = {
  title: 'V-65(a)(b) 🔴支払えば通る窓が実際に出て、支払うと本体（エナチャージ）が通る',
  spec: v65PayGateSpec,
  async drive(page, H) {
    const { fin, windowSeen } = await driveV65PayGate(page, H, true);
    // ⚠支払った分（filler）はtrashへ移り、ボーナスのエナチャージがそれを埋め合わせるため
    //   energy枚数だけでは判定できない（filler消費とボーナス+1が相殺されて数字が変わらない）。
    //   deckの消費量（WX01-049分1枚＋ボーナス分1枚=2枚）とtrashへの支払い移動で判定する。
    const deckFinal = fin?.host?.deck ?? -1;
    const paidCardInTrash = (fin?.host?.trashCards ?? []).includes('WD01-014#9983');
    const detail = `windowSeen=${windowSeen}（期待true） / deck終値=${deckFinal}（期待3＝5枚中2枚消費＝ボーナスも発火） / `
      + `paidCardInTrash=${paidCardInTrash}（期待true） / energy終値=${fin?.host?.energy} / logTail末尾=${JSON.stringify((fin?.logTail ?? []).slice(-6))}`;
    H.log(`  v65paygate ${detail}`);
    return { pass: windowSeen && deckFinal === 3 && paidCardInTrash, detail };
  },
};
