// ── V-24(cxiv) START ──
// §7 V-24(cxiv)＝条件つきキーワード付与（Opusタスク12(cxiv)修正済み＝execUtils.ts buildGatedKeywordGrant）。
// 旧＝GRANT_QUOTED_ABILITY が「正面のシグニのパワーがN以下であるかぎり」等のゲート条件を落として
// keyword_grants（無条件）へ入れていた＝正面が誰でも常時ランサーが付いていた。
// 修正後は granted_effects へ「activeCondition:FRONT_SIGNI_POWER」付きCONTINUOUSとして入り、
// collectContinuousGrantedKeywords が毎フレーム評価する（board上の静的バッジは無いためバトル結果で観測）。
// WXDi-P11-071（翠将バーバリアン）＝「正面のシグニのパワーが3000以下であるかぎり、【ランサー】を得る」を
// granted_effects へ直接注入（ONPLAYのコスト支払いUIを省略）し、【ランサー】の効果（バニッシュ時にライフ
// クロス1枚クラッシュ）が正面パワーの閾値の上下でON/OFFすることを観測する。
function v24cxivLancerGateSpec(frontCardNum, frontPower) {
  return {
    hostSet: {
      'field.check': null,
      'field.lrig': ['WD03-003#1'],
      'field.signi': [null, ['WXDi-P11-071#1'], null], // zone1＝中央（`2-zi`ミラーの不動点＝正面はguest zone1）
      'field.signi_down': [false, false, false],
      'granted_effects': {
        'WXDi-P11-071#1': [{
          effectId: 'granted-v24cxiv-lancer-gate',
          effectType: 'CONTINUOUS',
          duration: 'UNTIL_END_OF_TURN',
          mandatory: true,
          activeCondition: { type: 'FRONT_SIGNI_POWER', operator: 'lte', value: 3000 },
          action: {
            type: 'GRANT_KEYWORD',
            target: { type: 'SIGNI', owner: 'self', count: 1, filter: { thisCardOnly: true } },
            keyword: 'ランサー',
            duration: 'UNTIL_END_OF_TURN',
          },
        }],
      },
      // host が確実に勝てるよう十分にバフ（判定したいのは「勝敗」ではなく「ランサーのゲート」）。
      'temp_power_mods': [{ cardNum: 'WXDi-P11-071#1', delta: 6000 }],
      'actions_done': [],
    },
    guestSet: {
      'field.check': null,
      'field.signi': [null, [`${frontCardNum}#900`], null],
      'field.signi_down': [false, false, false],
      'life_cloth': ['WD01-013#800', 'WD01-013#801', 'WD01-013#802'],
    },
    top: { active: 'host', turn_phase: 'ATTACK_SIGNI', turn_count: 2 },
  };
}
async function driveV24cxivLancerGate(page, H, gateShouldBeOn) {
  const before = await H.queryState();
  const beforeLife = before?.guest?.life;
  H.log('開始時 guest.life:', beforeLife);
  let attacked = false;
  for (let s = 0; s < 40; s++) {
    await page.waitForTimeout(250);
    const st0 = await H.queryState();
    let did = null;
    if (!attacked) {
      did = await openSigniAttack(page, H, 1);
      if (did) attacked = true;
    }
    if (!did) did = await H.clickBtn('発動順序を確定', { exact: true });
    if (!did) did = await H.clickBtn('ガードしない（ライフクロスクラッシュ）', { exact: true });
    if (!did) did = await H.clickBtn('エナに送る', { exact: true });
    if (!did) did = await H.stdStep();
    const st = await H.queryState();
    const life = st?.guest?.life;
    await page.screenshot({ path: `${SHOT}/v24cxivLancerGate${gateShouldBeOn ? 'On' : 'Off'}-${s}.png`, fullPage: true }).catch(() => {});
    H.log(`  cxiv[${s}] -> did=${did ?? 'なし'} guestLife=${life} banished=${JSON.stringify(st?.guest?.fieldSigni)} pEff=${st?.pendingEffect ?? '-'} stack=${st?.stackLen ?? '-'} pOpts=${JSON.stringify(st?.pendingOptions ?? null)} pCands=${JSON.stringify(st?.pendingCandidates ?? null)}`);
    if (attacked && s > 3 && st?.pendingEffect == null && st?.stackLen === 0) {
      const gone = !(st?.guest?.fieldSigni?.[1]?.length);
      if (!gone) continue; // まだバニッシュ未解決
      const dropped = typeof beforeLife === 'number' && typeof life === 'number' && life < beforeLife;
      if (gateShouldBeOn) {
        if (dropped) return { pass: true, detail: `正面パワー3000以下＝ランサー成立→バニッシュ後にライフクロスクラッシュを確認（before=${beforeLife} after=${life}）` };
      } else {
        if (!dropped) return { pass: true, detail: `正面パワー3000超＝ランサー不成立→バニッシュのみでライフクロス変化なしを確認（before=${beforeLife} after=${life}）` };
        return { pass: false, detail: `🔴正面パワー3000超なのにライフクロスがクラッシュした（旧バグ＝ゲート無視で常時ランサー。before=${beforeLife} after=${life}）` };
      }
    }
  }
  const fin = await H.queryState();
  return { pass: false, detail: `判定不能（did未到達 or 未解決。fin.guest.life=${fin?.guest?.life} fieldSigni=${JSON.stringify(fin?.guest?.fieldSigni)} pEff=${fin?.pendingEffect ?? '-'}）` };
}
scenarios.v24cxivLancerGateOn = {
  title: 'V-24(cxiv) WXDi-P11-071＝正面パワー3000以下（ゲート成立）でランサー→バニッシュ時にライフクロスクラッシュ',
  spec: v24cxivLancerGateSpec('WD01-013', 3000),
  async drive(page, H) { return driveV24cxivLancerGate(page, H, true); },
};
order.push('v24cxivLancerGateOn');
scenarios.v24cxivLancerGateOff = {
  title: 'V-24(cxiv) 対照：WXDi-P11-071＝正面パワー3000超（ゲート不成立）ではランサー不発→ライフクロス変化なし',
  spec: v24cxivLancerGateSpec('WD01-016', 5000),
  async drive(page, H) { return driveV24cxivLancerGate(page, H, false); },
};
order.push('v24cxivLancerGateOff');
// ── V-24(cxiv) END ──

// ── V-24(cxiii) START ──
// §7 V-24(cxiii)＝WXK10-035（コードＶＬ　リゼ・ヘルエスタ）の効果耐性。
// E1（subscriber_count<50）＝あなたの＜電機＞のシグニは対戦相手のレベル1以下のシグニの効果を受けない
// （collectEffectImmuneSigni が GRANT_PROTECTION{sourceFilter:{level:{max:1}}} を読む＝BattleScreen.tsx:4762
// の1箇所だけ）。wd07012 と同型＝guestの攻撃シグニにON_ATTACK_SIGNI granted BANISHを注入しCPU自動アタックで
// 発火させ、host（電機）が候補から除外される（レベル1＝生存）／除外されない（レベル2＝バニッシュ）を見る。
function v24cxiiiImmuneSpec(attackerCardNum) {
  return {
    hostSet: {
      'field.check': null,
      'field.signi': [null, null, ['WXK10-035#1']], // 自zone2＝攻撃側zone0の正面（wd07012と同型）
      'field.signi_down': [false, false, false],
      'subscriber_count': 0, // <50＝E1（レベル1以下のシグニの効果を受けない）が有効
      // 印字3000のままだと攻撃側と同パワーで通常バトルだけで（旧＝BANISH能力と無関係に）バニッシュされてしまう
      // ＝BANISH能力の効果耐性だけを切り分けるため、通常バトルでは絶対に負けないようバフする。
      'temp_power_mods': [{ cardNum: 'WXK10-035#1', delta: 6000 }],
      'actions_done': [],
    },
    guestSet: {
      'field.check': null,
      'field.signi': [[`${attackerCardNum}#1`], null, null],
      'field.signi_down': [false, false, false],
      'blocked_actions': [],
      'granted_effects': {
        [`${attackerCardNum}#1`]: [{
          effectId: 'granted-v24cxiii-banish',
          effectType: 'AUTO',
          timing: ['ON_ATTACK_SIGNI'],
          triggerScope: 'self',
          duration: 'INSTANT',
          mandatory: true,
          action: { type: 'BANISH', target: { type: 'SIGNI', owner: 'opponent', count: 1, filter: { cardType: 'シグニ' }, upToCount: false } },
        }],
      },
    },
    top: { active: 'cpu', turn_phase: 'ATTACK_SIGNI', turn_count: 3 },
  };
}
async function driveV24cxiii(page, H, expectImmune) {
  const before0 = await H.queryState();
  H.log('注入直後 host.fieldSigni:', JSON.stringify(before0?.host?.fieldSigni), 'guest.fieldSigni:', JSON.stringify(before0?.guest?.fieldSigni), 'active:', before0?.activeUser);
  for (let s = 0; s < 20; s++) {
    await page.waitForTimeout(1000);
    await page.screenshot({ path: `${SHOT}/v24cxiii${expectImmune ? 'Immune' : 'NotImmune'}-${s}.png`, fullPage: true }).catch(() => {});
    const st = await H.queryState();
    H.log(`  cxiii[${s}] -> hostFieldSigni=${JSON.stringify(st?.host?.fieldSigni)} pEff=${st?.pendingEffect ?? '-'} stack=${st?.stackLen ?? '-'}`);
    await H.clickTextOrBtn(['ガードしない', 'しない', '使用しない', '通常通り', 'いいえ', 'スキップ']);
    if (st?.pendingEffect == null && st?.stackLen === 0 && s > 2) {
      const survived = !!(st?.host?.fieldSigni?.[2]?.length);
      if (expectImmune) {
        if (survived) return { pass: true, detail: `レベル1のシグニのBANISHは効果耐性で不発＝WXK10-035が生存を確認（fieldSigni=${JSON.stringify(st.host.fieldSigni)}）` };
      } else {
        if (!survived) return { pass: true, detail: `レベル2のシグニのBANISHは耐性対象外＝WXK10-035がバニッシュされたことを確認（fieldSigni=${JSON.stringify(st.host.fieldSigni)}）` };
      }
    }
  }
  const fin = await H.queryState();
  const survived = !!(fin?.host?.fieldSigni?.[2]?.length);
  if (expectImmune && !survived) return { pass: false, detail: `🔴レベル1のシグニの効果なのにバニッシュされた（耐性が効いていない。fieldSigni=${JSON.stringify(fin?.host?.fieldSigni)}）` };
  if (!expectImmune && survived) return { pass: false, detail: `レベル2のシグニなのにバニッシュされなかった（過剰保護 or CPU未行動。fieldSigni=${JSON.stringify(fin?.host?.fieldSigni)}）` };
  return { pass: false, detail: `判定不能（fin.fieldSigni=${JSON.stringify(fin?.host?.fieldSigni)} pEff=${fin?.pendingEffect ?? '-'}）` };
}
