    H.log('ルリグDK:', await H.clickTestId('my-lrig-dk') ?? '見つからず');
    await page.waitForTimeout(600);
    H.log('ピース(zone-card-0):', await H.clickTestId('zone-card-0') ?? '見つからず');
    let usedBtn = false;
