order.push('v58acWindowOpensAndPassResolvesOriginal', 'v58dChoice1CountersAndExilesOriginal', 'v58eChoice2DrawsChargesThenOriginalResolves');
// ── V-58(a)(c)(d)(e) END ──

// ── V-35(b)(c) START ──
// §7 V-35(b)(c)（続き497＝O-3 是正）＝`WDK06-R09-E1`（メル＝マドラー・キー）：
// 【自】対戦相手のターン終了時、このターンにアタックしたシグニを２体まで対象とし、
// このキーを場からルリグトラッシュに置いてもよい。そうした場合、それらをバニッシュする。
// 旧実装は対象・コスト・所有者の3点すべて誤りで「相手のターン終了時に自分のシグニを1体タダでバニッシュ」
// していた（BUGFIXES 2026-08-15続き497）。是正後の3経路を実UIで確認する：
//   (b-pay)  候補は「このターンにアタックした相手シグニ」だけ（未アタックの3体目は候補に出ない）／
//            キーを払うと選んだ2体がバニッシュされる／自分のシグニは減らない。
//   (b-skip) 同じ候補が出ても支払わなければ何も起きない（相手シグニ・自分のキーとも無傷）。
//   (c)      場にキーが無ければ支払い枝（optcost-pay）が出ない/使えない。
//
// 🔴🆕2026-08-19＝3本とも実UIでタイムアウトFAIL（pendingEffect が一度も立たず、CPUターン終了が素通りして
// 次ターンのUPフェイズへ進む＝ON_TURN_END トリガー自体が収集されていない）。原因は STUB 側ではなく
// **収集側の配線漏れ**＝`src/engine/triggerCollect.ts` の `collectTurnTriggers`（ON_TURN_START/ON_TURN_END/
// ON_ATTACK_PHASE_START・END/ON_GROW_PHASE_START/ON_MAIN_PHASE_START/ON_LRIG_ATTACK_STEP_START の共通収集器）は
// 自陣・相手陣とも `field.signi` とセンタールリグ・付与ストアしか走査せず、`activeKeyAbilitySources()`
// （`effectEngine.ts`＝`field.key_piece`＋`key_piece_extra`）を一度も呼んでいない。兄弟収集器の
// `collectLrigGrowTriggers`（:671）と `collectSigniDownUpTriggers`（:2375）は `activeKeyAbilitySources` を
// 呼んでおり、キー起点の【自】がそちらの timing では発火する非対称な穴。**Sonnetは engine を直さない規約**
// のため据置＝Opusタスク12 (cxliii) へ登録（PLAN §3・§4）。**シナリオは残すが `order` には入れない**
// （既定バッチは意図的FAILで汚さない＝続き436 の kokona* と同型の扱い。修正が着地したら order.push へ復帰）。
const WDK06_GUEST_ATK1 = 'WD01-012#9611'; // このターンにアタックした（候補になるべき）
const WDK06_GUEST_ATK2 = 'WD01-012#9612'; // 同上
const WDK06_GUEST_SAFE = 'WD01-012#9613'; // 未アタック（候補に出てはいけない）
const WDK06_HOST_SIGNI = 'WD01-013#9601'; // 自分のシグニ（減ってはいけない対照）
const WDK06_KEY = 'WDK06-R09#9602';
function wdk06r09Spec(hasKey) {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#9600'],
      'field.signi': [[WDK06_HOST_SIGNI], null, null],
      'field.signi_down': [false, false, false],
      'field.key_piece': hasKey ? WDK06_KEY : null,
      'field.key_piece_extra': [],
      'field.check': null,
      'hand': [], 'energy': [], 'trash': [], 'lrig_trash': [],
      'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#9610'],
      'field.signi': [[WDK06_GUEST_ATK1], [WDK06_GUEST_ATK2], [WDK06_GUEST_SAFE]],
      'field.signi_down': [false, false, false],
      'field.check': null,
      'attacked_signi_ids': [WDK06_GUEST_ATK1, WDK06_GUEST_ATK2],
      'actions_done': [],
    },
    top: { active: 'cpu', turn_phase: 'END', turn_count: 3 },
  };
}
function wdk06r09CandidatesOk(cands) {
  return Array.isArray(cands) && cands.length === 2
    && cands.includes(WDK06_GUEST_ATK1) && cands.includes(WDK06_GUEST_ATK2)
    && !cands.includes(WDK06_GUEST_SAFE);
}
scenarios.wdk06r09Pay = {
  title: 'V-35(b) WDK06-R09-E1 pay：アタック済み2体だけ候補→キーを払うと両方バニッシュ・自分のシグニは無傷',
  spec: wdk06r09Spec(true),
  async drive(page, H) {
    const before = await H.queryState();
    H.log('開始時 guest.fieldSigni:', JSON.stringify(before?.guest?.fieldSigni), 'host.keyPiece:', before?.host?.keyPiece);
    let candidatesChecked = false; const picked = new Set(); let targetsConfirmed = false; let paid = false;
    const picked2 = new Set();   // 支払い後の再確認 SELECT_TARGET 用（トグル対策）
    for (let s = 0; s < 40; s++) {
      await page.waitForTimeout(700);
      let did = null;
      const st0 = await H.queryState();
      if (!targetsConfirmed && Array.isArray(st0?.pendingCandidates) && st0.pendingCandidates.length) {
        if (!candidatesChecked) {
          candidatesChecked = wdk06r09CandidatesOk(st0.pendingCandidates);
          if (!candidatesChecked) return { pass: false, detail: `候補が不正: ${JSON.stringify(st0.pendingCandidates)}（期待=アタック済み2体のみ・未アタック3体目は含まない）` };
        }
        for (let i = 0; i < st0.pendingCandidates.length; i++) {
          if (picked.has(i)) continue;
          const p = await H.clickTestId(`pick-${i}`);
          if (p) { picked.add(i); did = p; break; }
        }
        if (!did && picked.size >= st0.pendingCandidates.length) did = await H.clickBtn('決定');
        if (did === 'btn:決定') targetsConfirmed = true;
      }
      if (!did && targetsConfirmed && !paid) {
        const pay = await H.clickTestId('optcost-pay');
        if (pay) { did = pay; paid = true; }
      }
      // ⚠**支払いの後にもう一度 SELECT_TARGET が出る**（`fixedCardNums` で2件に絞られた再確認＝
      //   `lxivMultiTargetPayBanishesBoth` と同じ形）。ここを解決しないと `pEff=SELECT_TARGET` のまま
      //   40ティック空振りする（2026-08-24 実測＝engine 修正後にこの段まで進めるようになって初めて露見した）。
      if (!did && paid) {
        const st1 = await H.queryState();
        const n2 = Array.isArray(st1?.pendingCandidates) ? st1.pendingCandidates.length : 0;
        // ⚠🔴**候補は1つにつき1回だけ押す**＝同じ index を押し直すと**トグルで選択が外れ**、
        //   永久に決定へ到達しない（V-19 でも踏んだ既知の罠）。押した index を集合で覚える。
        if (n2 > 0 && picked2.size < n2) {
          for (let i = 0; i < n2; i++) {
            if (picked2.has(i)) continue;
            const p2 = await H.clickTestId(`pick-${i}`);
            if (p2) { picked2.add(i); did = p2; break; }
          }
        }
        if (!did) did = await clickDecideNofM(page);
      }
      const st = await H.queryState();
      H.log(`  wdk06pay[${s}] -> ${did ?? 'なし'} | phase=${st?.turnPhase} active=${st?.activeUser} viewer=${st?.viewerUserId} stackLen=${st?.stackLen} candOk=${candidatesChecked} picked=${[...picked]} confirmed=${targetsConfirmed} paid=${paid} gField=${JSON.stringify(st?.guest?.fieldSigni)} hKey=${st?.host?.keyPiece} hLrigTrash=${st?.host?.lrigTrashCards} pEff=${st?.pendingEffect ?? '-'} opts=${JSON.stringify(st?.pendingOptions)}`);
      if (paid && !st?.pendingEffect) {
        const gAlive = (st?.guest?.fieldSigni ?? []).flat().filter(Boolean);
        const banishedBoth = !gAlive.includes(WDK06_GUEST_ATK1) && !gAlive.includes(WDK06_GUEST_ATK2) && gAlive.includes(WDK06_GUEST_SAFE);
        const keyGone = st.host.keyPiece == null && (st.host.lrigTrashCards ?? []).includes(WDK06_KEY);
        const hostSigniIntact = (st.host.fieldSigni ?? []).flat().filter(Boolean).includes(WDK06_HOST_SIGNI);
        const ok = candidatesChecked && banishedBoth && keyGone && hostSigniIntact;
        return { pass: ok, detail: `候補限定=${candidatesChecked}・攻撃済み2体バニッシュ=${banishedBoth}（残存=${JSON.stringify(gAlive)}）・キー消費=${keyGone}・自分シグニ健在=${hostSigniIntact}` };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cand=${candidatesChecked} confirmed=${targetsConfirmed} paid=${paid} pEff=${fin?.pendingEffect ?? '-'} opts=${JSON.stringify(fin?.pendingOptions)}）` };
  },
};
scenarios.wdk06r09Skip = {
  title: 'V-35(b) WDK06-R09-E1 skip対照：同じ候補が出ても支払わなければ何も起きない',
  spec: wdk06r09Spec(true),
  async drive(page, H) {
    const before = await H.queryState();
    H.log('開始時 guest.fieldSigni:', JSON.stringify(before?.guest?.fieldSigni), 'host.keyPiece:', before?.host?.keyPiece);
    let candidatesChecked = false; const picked = new Set(); let targetsConfirmed = false; let skipped = false;
    for (let s = 0; s < 40; s++) {
      await page.waitForTimeout(700);
      let did = null;
      const st0 = await H.queryState();
      if (!targetsConfirmed && Array.isArray(st0?.pendingCandidates) && st0.pendingCandidates.length) {
        if (!candidatesChecked) {
          candidatesChecked = wdk06r09CandidatesOk(st0.pendingCandidates);
          if (!candidatesChecked) return { pass: false, detail: `候補が不正: ${JSON.stringify(st0.pendingCandidates)}` };
        }
        for (let i = 0; i < st0.pendingCandidates.length; i++) {
          if (picked.has(i)) continue;
          const p = await H.clickTestId(`pick-${i}`);
          if (p) { picked.add(i); did = p; break; }
        }
        if (!did && picked.size >= st0.pendingCandidates.length) did = await H.clickBtn('決定');
        if (did === 'btn:決定') targetsConfirmed = true;
      }
      if (!did && targetsConfirmed && !skipped) {
        const skip = await H.clickTestId('optcost-skip');
        if (skip) { did = skip; skipped = true; }
      }
      const st = await H.queryState();
      H.log(`  wdk06skip[${s}] -> ${did ?? 'なし'} | candOk=${candidatesChecked} confirmed=${targetsConfirmed} skipped=${skipped} gField=${JSON.stringify(st?.guest?.fieldSigni)} hKey=${st?.host?.keyPiece} pEff=${st?.pendingEffect ?? '-'} opts=${JSON.stringify(st?.pendingOptions)}`);
      if (skipped && !st?.pendingEffect) {
        const gAlive = (st?.guest?.fieldSigni ?? []).flat().filter(Boolean);
        const untouched = [WDK06_GUEST_ATK1, WDK06_GUEST_ATK2, WDK06_GUEST_SAFE].every(c => gAlive.includes(c));
        const keyIntact = st.host.keyPiece === WDK06_KEY;
        const ok = candidatesChecked && untouched && keyIntact;
        return { pass: ok, detail: `候補限定=${candidatesChecked}・skip後も相手シグニ3体健在=${untouched}（${JSON.stringify(gAlive)}）・自分のキー健在=${keyIntact}` };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cand=${candidatesChecked} confirmed=${targetsConfirmed} skipped=${skipped} pEff=${fin?.pendingEffect ?? '-'} opts=${JSON.stringify(fin?.pendingOptions)}）` };
  },
};
scenarios.wdk06r09NoKey = {
  title: 'V-35(c) 対照：場にキーが無ければ「相手のターン終了時」の窓自体が開かない',
  spec: wdk06r09Spec(false),
  async drive(page, H) {
    // 🔴**2026-08-24 に期待値を書き換えた（シナリオの腐り）**＝旧版は「候補は出るが pay 枝が
    //   disabled」を期待していたが、**この【自】はキー（`WDK06-R09`）自身の能力**なので、
    //   キーが場に無ければ `activeKeyAbilitySources` が拾わず**能力そのものが存在しない**
    //   ＝**窓が一度も開かないのが正**（engine 修正後に実機で確認）。
    // 🔑**対照は同じ盤面でキーだけを載せた `wdk06r09Pay`／`wdk06r09Skip`**＝あちらでは窓が開く。
    //   「何も起きない」を単独で緑にしない（§4.4 の3）。
    const before = await H.queryState();
    H.log('開始時 host.keyPiece:', before?.host?.keyPiece, 'guest.attacked:', JSON.stringify(before?.guest?.fieldSigni));
    let sawWindow = false; let quiet = 0;
    for (let s = 0; s < 20; s++) {
      await page.waitForTimeout(700);
      const st = await H.queryState();
      if (st?.pendingEffect) sawWindow = true;
      H.log(`  wdk06nokey[${s}] | sawWindow=${sawWindow} pEff=${st?.pendingEffect ?? '-'} stack=${st?.stackLen ?? '-'} phase=${st?.turnPhase} gField=${JSON.stringify(st?.guest?.fieldSigni)} hKey=${st?.host?.keyPiece}`);
      quiet = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? quiet + 1 : 0;
      if (sawWindow) {
        return { pass: false, detail: `【回帰】キーが無いのに窓が開いた（pEff=${st?.pendingEffect}）` };
      }
      if (quiet >= 6) {
        const gAlive = (st?.guest?.fieldSigni ?? []).flat().filter(Boolean);
        const allAlive = [WDK06_GUEST_ATK1, WDK06_GUEST_ATK2, WDK06_GUEST_SAFE].every(n => gAlive.includes(n));
        const hostIntact = (st?.host?.fieldSigni ?? []).flat().filter(Boolean).includes(WDK06_HOST_SIGNI);
        return {
          pass: allAlive && hostIntact && st?.host?.keyPiece == null,
          detail: `キー無し＝窓は開かない（sawWindow=${sawWindow}）／相手のアタック済み2体を含む3体とも健在=${allAlive}／自分のシグニも無傷=${hostIntact}`,
        };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（sawWindow=${sawWindow} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
// ⚠意図的に order へは入れない（Opusタスク12(cxliii) 修正待ち＝上のコメント参照）。
// 修正後は `node scripts/verifyBattleDrive.mjs wdk06r09Pay wdk06r09Skip wdk06r09NoKey` で単体確認してから復帰する。
// ── V-35(b)(c) END ──

// ── V-28 START ──
// §7 V-28（続き412＝O-13 A群5件目・§6.4）＝`WX16-021`（驚天動地）：
// 「このターン、あなたの＜英知＞のシグニがシグニのない対戦相手のシグニゾーンにアタックする場合、
// 代わりにそのアタックではそのシグニゾーンの正面にあるかのように対戦相手にダメージを与える。」
// 実装（`screens/battle/sideAttackDamage.ts`）は**2箇所**（①側面アタックの空ゾーン先ボタン生成
// ②`resolvePendingSigniBattleFor`の解決）を同じ`sideAttackEmptyZoneDealsDamage`で判定する設計＝
// 両方を実UIで見る（**負方向＋対照の対**）。【側面アタック】キーワード自体は`keyword_grants`で直接付与
// （native付与元カードの正否はこのシナリオの対象外＝WX16-021単体の挙動を切り分ける）。
const WX16021_ATTACKER = 'WX15-054#9701'; // 四英の掛算（精像：英知・Lv3）＝側面アタックを直接付与
function wx16021Spec(turnPhase) {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#9700'],
      'field.signi': [null, [WX16021_ATTACKER], null], // 中央（zone1）に配置＝frontOpZone=2-1=1、隣接0/2が側面
      'field.signi_down': [false, false, false],
      'field.check': null,
      'keyword_grants': { [WX16021_ATTACKER]: ['側面アタック'] },
      'lrig_deck': ['WX16-021#9702'],
      'hand': [], 'energy': [], 'trash': [], 'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#9710'],
      'field.signi': [null, null, null], // 全ゾーン空＝側面アタック先(zone0/zone2)も前面(zone1)も空
      'field.signi_down': [false, false, false],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: turnPhase, turn_count: 2 },
  };
}scenarios.wx16021SideAttackEmptyZoneNoButtonBeforeArts = {
  title: 'V-28 WX16-021 対照：驚天動地を使う前は空ゾーンへの側面アタックボタン自体が出ない',
  spec: wx16021Spec('ATTACK_SIGNI'), // アタック系ボタンはATTACK_SIGNIフェイズでのみ生成される
  async drive(page, H) {
    const opened = await H.clickTestId('my-signi-zone-1');
    await page.waitForTimeout(700);
    const cnt = await page.getByRole('button', { name: /側面アタック/ }).count();
    const atkCnt = await page.getByRole('button', { name: 'アタック', exact: true }).count();
    await H.closeModals();
    return {
      pass: cnt === 0 && atkCnt >= 1,
      detail: cnt === 0 && atkCnt >= 1
        ? `モーダル開通確認（アタックボタン${atkCnt}個）のうえで側面アタックボタンは0個（emptyZoneDamages=false）＝空ゾーンは提示されない（opened=${opened}）`
        : `【異常】opened=${opened} atkCnt=${atkCnt} 側面アタック=${cnt}個`,
    };
  },
};
scenarios.wx16021SideAttackEmptyZoneDamageAfterArts = {
  title: 'V-28 WX16-021 正方向：驚天動地を使うと空ゾーンへの側面アタックが正面扱いでダメージになる',
  spec: wx16021Spec('MAIN'), // MAINで驚天動地を使ってからATTACK_SIGNIへ進める
  async drive(page, H) {
    const before = await H.queryState();
    await H.ensureMain();
    H.log('開始時 guest.life:', before?.guest?.life);
    let castDone = false; let advanced = false; let attacked = false; let closedLrigDk = false;
    for (let s = 0; s < 30; s++) {
      await page.waitForTimeout(800);
      let did = null;
      const st0 = await H.queryState();
      if ((st0?.logTail ?? []).some(l => l.includes('驚天動地'))) castDone = true;
      if (!castDone) {
        // アーツはルリグデッキから使う：ルリグDKバッジ→カード→使用→アーツ使用（緑×0＝コスト選択不要）。
        const use = page.getByRole('button', { name: /アーツ使用/ }).first();
        if (await use.count() && await use.isVisible().catch(() => false) && await use.isEnabled().catch(() => false)) {
          await use.click().catch(() => {}); did = 'btn:アーツ使用';
        }
        if (!did) did = await H.clickTextOrBtn(['使用']);
        if (!did) did = await H.clickTestId('zone-card-0');
        if (!did) did = await H.clickTestId('my-lrig-dk');
      } else if (!closedLrigDk) {
        // castDone判定がstCast側の反映ラグで1手遅れ、次のフォールバックがmy-lrig-dkバッジを再クリックして
        // ルリグデッキ一覧を再度開いてしまうことがある＝背面のフェイズボタンへのクリックを吸収する
        // オーバーレイになる（実測＝locator.click timeoutで「subtree intercepts pointer events」）。
        // 一覧が開いていれば同じバッジをもう一度押してトグルで閉じてから進める。
        const dkOpen = await page.getByTestId('zone-card-0').count();
        if (dkOpen > 0) { did = await H.clickTestId('my-lrig-dk'); }
        closedLrigDk = true;
      } else if (!advanced) {
        await H.closeModals();
        did = await H.clickTextOrBtn(['アタックフェイズへ']);
        // MAIN→ATTACK_ARTS（自分のアーツステップ）を経由する＝素の「アタックフェイズへ」1クリックでは
        // ATTACK_SIGNIまで進まない。アーツを使わずスキップしてシグニアタックへ進める。
        if (!did) did = await H.clickTextOrBtn(['アーツ終了→相手へ', 'アーツ終了', 'アーツステップ終了', 'シグニアタックへ']);
        if (!did) did = await H.stdStep(['パス（カットインしない）', 'パス', 'スキップ']);
        const stAdv = await H.queryState();
        if (stAdv?.turnPhase === 'ATTACK_SIGNI') advanced = true;
      } else if (!attacked) {
        if (!did) did = await H.clickBtn('側面アタック→空きゾーン（ダメージ）', { exact: false });
        if (!did) did = await H.clickTestId('my-signi-zone-1');
        if (did === '側面アタック→空きゾーン（ダメージ）' || did?.startsWith('btn:側面アタック')) attacked = true;
      }
      const st = await H.queryState();
      H.log(`  wx16021[${s}] -> ${did ?? 'なし'} | castDone=${castDone} advanced=${advanced} attacked=${attacked} phase=${st?.turnPhase} gLife=${st?.guest?.life} pEff=${st?.pendingEffect ?? '-'} logTail末尾=${JSON.stringify((st?.logTail ?? []).slice(-2))}`);
      if (attacked && (st?.guest?.life ?? before.guest.life) < before.guest.life) {
        return { pass: true, detail: `驚天動地使用後、空ゾーンへの側面アタックでguest.life ${before.guest.life}→${st.guest.life}（正面扱いダメージが通った）` };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（castDone=${castDone} attacked=${attacked} gLife=${before.guest.life}→${fin?.guest?.life} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('wx16021SideAttackEmptyZoneNoButtonBeforeArts', 'wx16021SideAttackEmptyZoneDamageAfterArts');

// §7 V-28 続き＝A群1件目`CANNOT_DEAL_DAMAGE_TO_OPPONENT`（`WX25-CP1-074`）：
// 【出】が他の＜ブルアカ＞シグニに「【常】：このシグニは対戦相手にダメージを与えない。」を付与する。
// 判定点（`screens/battle/signiDamageGate.ts`）は2つのダメージ地点（ランサー等の追加クラッシュ／正面空の
// 直接ライフアタック）で共通に呼ばれる＝ここでは(b)正面が空の直接ライフアタックで確認（付与は`granted_effects`で直接注入）。
const CDDTO_ATTACKER = 'WD01-013#9801';
function cddtoSpec(granted) {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#9800'],
      'field.signi': [null, [CDDTO_ATTACKER], null], // 中央zone1＝相手の正面(2-1=1)を突く
      'field.signi_down': [false, false, false],
      'field.check': null,
      'granted_effects': granted ? {
        [CDDTO_ATTACKER]: [{
          effectId: 'granted-cddto-cont', effectType: 'CONTINUOUS', duration: 'UNTIL_END_OF_TURN', mandatory: true,
          action: { type: 'STUB', id: 'CANNOT_DEAL_DAMAGE_TO_OPPONENT' },
        }],
      } : {},
      'hand': [], 'energy': [], 'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#9810'],
      'field.signi': [null, null, null], // 全ゾーン空＝正面(zone1)も空＝直接ライフアタック経路
      'field.signi_down': [false, false, false],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'ATTACK_SIGNI', turn_count: 2 },
  };
}
async function driveCddto(page, H, expectBlocked) {
  const before = await H.queryState();
  H.log('開始時 guest.life:', before?.guest?.life);
  let attacked = false; let opened = false;
  for (let s = 0; s < 20; s++) {
    await page.waitForTimeout(800);
    let did = null;
    if (!attacked) {
      did = await H.clickBtn('アタック', { exact: true });
      if (did) attacked = true;
      else if (!opened) { did = await H.clickTestId('my-signi-zone-1'); opened = true; }
    }
    const st = await H.queryState();
    H.log(`  cddto[${s}] -> ${did ?? 'なし'} | attacked=${attacked} gLife=${st?.guest?.life} pEff=${st?.pendingEffect ?? '-'}`);
    if (attacked && st?.pendingEffect == null && (st?.stackLen ?? 0) === 0 && s >= 3) {
      const crashed = (st?.guest?.life ?? before.guest.life) < before.guest.life;
      const ok = expectBlocked ? !crashed : crashed;
      return {
        pass: ok,
        detail: expectBlocked
          ? (crashed ? `🔴CANNOT_DEAL_DAMAGE_TO_OPPONENT付与中なのにguest.lifeが減った（${before.guest.life}→${st.guest.life}）` : `付与どおりダメージなし（guest.life ${before.guest.life}→${st.guest.life} 不変）`)
          : (crashed ? `対照＝付与なしは通常どおりguest.life ${before.guest.life}→${st.guest.life}` : `🔴対照なのにダメージが通らなかった`),
      };
    }
  }
  const fin = await H.queryState();
  return { pass: false, detail: `未完了（attacked=${attacked} gLife=${before.guest.life}→${fin?.guest?.life} pEff=${fin?.pendingEffect ?? '-'}）` };
}
scenarios.cddtoBlocksDirectLifeDamage = {
  title: 'V-28 WX25-CP1-074 正方向：CANNOT_DEAL_DAMAGE_TO_OPPONENT付与中は正面空への直接アタックでもライフが減らない',
  spec: cddtoSpec(true),
  async drive(page, H) { return driveCddto(page, H, true); },
};
scenarios.cddtoControlDamageNormally = {
  title: 'V-28 WX25-CP1-074 対照：付与なしなら正面空への直接アタックで通常どおりライフが減る',
  spec: cddtoSpec(false),
  async drive(page, H) { return driveCddto(page, H, false); },
};
order.push('cddtoBlocksDirectLifeDamage', 'cddtoControlDamageNormally');

