// V-40(b)：`USE_SEARCHED_SPELL_OR_TRASH`＝`WX20-077-E2`（ドライ＝アコニチン）【出】：自トラッシュに
// カード名に《リカブト》を含むカードがあれば、デッキから《バイオレンス・スプラッシュ》をサーチ→
// シャッフル→「コストを支払わずに使用する／トラッシュに置く」のCHOOSE。
// 🔴実機検証で新規バグを発見＝SEARCHインタラクションが描画されず画面が真っ黒になる（React crash）。
// 真因＝`parseSentencePart3.ts:1856-1868` が生成する SEARCH アクションに **必須フィールド `then` が無い**
// （`then: EffectAction` は `types/effects.ts:1356` で必須宣言）。`EffectInteractionModal.tsx:119`
// （`const act = inter.thenAction; ... act.type === ...`）が `inter.thenAction===undefined` で
// `Cannot read properties of undefined (reading 'type')` を投げ、モーダルごと描画不能になる
// （pageerror で実機確認）。`effectExecutor.ts:8189` 以降のpick解決側も同じ前提で `pending.thenAction.type`
// を無条件参照しており、たとえ描画をバイパスできても resolver 側でも同様に crash する二重の穴。
// 母集団は現状 live 上 `then` 欠落の SEARCH は1件のみ（`WX20-077-E2`）と実測済み。
// 🏁**2026-08-20 続き589（Opusタスク12(cxlv)）で修正済み**＝parser が `then: ADD_TO_HAND{self}` を出し、
//   `EffectInteractionModal` も `thenAction` 未定義に耐えるようになった。⚠上記の「resolver 側にも同型の穴」は
//   **実測で誤りだった**＝`resumeSearch`（`effectExecutor.ts:8368`）は元から同じ既定へフォールバックしている。
// ⚠旧シナリオ ID は `v40UseSearchedSpellOrTrashCrash`（＝SEARCH が pending のままなら PASS を返さない記録用）。
//   修正後はモーダルが正常描画されるので、**探す→手札へ→「使用/トラッシュ」二択→トラッシュ**まで通す正常系へ書き換えた。
scenarios.v40UseSearchedSpellOrTrashResolves = {
  title: 'V-40(b) WX20-077-E2：SEARCHモーダルが描画され、探した札が「使用/トラッシュ」二択まで進む(cxlv)',
  spec: {
    hostSet: {
      'field.lrig': ['WD01-001#40100'],
      // ⚠空きシグニゾーン3のまま召喚するとブラウザがクラッシュする既知の罠（続き580）＝zone0にfillerを置いて2に減らす。
      'field.signi': [['WD01-013#40199'], null, null],
      'field.check': null,
      'trash': ['WX04-037#40101'],
      'deck': ['WX04-038#40102', 'WD01-013#40103', 'WD01-013#40104'],
      'energy': [], 'actions_done': [], 'hand': [],
    },
    handPrepend: ['WX20-077#40105'],
    guestSet: {
      'field.lrig': ['WD01-001#40110'],
      'field.signi': [null, null, null],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  },
  async drive(page, H) {
    await H.ensureMain();
    H.log('手札クリック(WX20-077):', await H.clickTestId('my-hand-card-0') ?? '見つからず');
    let summoned = false; let modalSeen = false; let chooseSeen = false; let emptyStreak = 0;
    for (let s = 0; s < 16; s++) {
      await page.waitForTimeout(700);
      await page.screenshot({ path: `${SHOT}/v40UseSearchedSpellOrTrash-${s}.png`, fullPage: true }).catch(() => {});
      let did = null;
      if (!summoned) {
        did = await H.clickTestId('summon-zone-0', 'summon-zone-1', 'summon-zone-2');
        if (did) summoned = true;
        if (!did) {
          const summonBtn = page.getByRole('button', { name: '召喚', exact: true }).first();
          if (await summonBtn.count() && await summonBtn.isVisible().catch(() => false)) {
            await summonBtn.click().catch(() => {}); did = 'btn:召喚';
          }
        }
      } else {
        const st0 = await H.queryState();
        if (st0?.pendingEffect === 'SEARCH') {
          // 🔴回帰ガード＝ここでモーダルが描画されず本文が空なら (cxlv) の再発（React crash）。
          if (!modalSeen) {
            const body = await H.body();
            modalSeen = body.includes('手札に加えるカードを');
            H.log(`    SEARCHモーダル描画=${modalSeen}（bodyText長=${body.length}）`);
          }
          did = await H.stdStep();                       // pick-0 → 決定
        } else {
          // 「使用する／トラッシュに置く」の二択（既存 USE_SEARCHED_SPELL_OR_TRASH）
          const trashBtn = page.getByRole('button', { name: /トラッシュに置く/ }).first();
          if (await trashBtn.count() && await trashBtn.isVisible().catch(() => false)) {
            await trashBtn.click().catch(() => {}); did = 'btn:トラッシュに置く'; chooseSeen = true;
          }
          if (!did) did = await H.stdStep();
        }
      }
      const st = await H.queryState();
      H.log(`  v40b[${s}] -> ${did ?? 'なし'} | summoned=${summoned} modalSeen=${modalSeen} chooseSeen=${chooseSeen} pEff=${st?.pendingEffect ?? '-'} hand=${JSON.stringify(st?.host?.handCards)} trash=${JSON.stringify(st?.host?.trashCards)}`);
      emptyStreak = (summoned && chooseSeen && !st?.pendingEffect) ? emptyStreak + 1 : 0;
      if (emptyStreak >= 2) {
        const inTrash = (st.host.trashCards ?? []).some(n => n.startsWith('WX04-038#40102'));
        const inHand = (st.host.handCards ?? []).some(n => n.startsWith('WX04-038#40102'));
        return {
          pass: modalSeen && inTrash && !inHand,
          detail: `SEARCHモーダル描画=${modalSeen}・二択到達=${chooseSeen}・《バイオレンス・スプラッシュ》trash=${inTrash}/hand=${inHand}（手札に残さないのが原文どおり）`,
        };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（summoned=${summoned} modalSeen=${modalSeen} chooseSeen=${chooseSeen} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('v40UseSearchedSpellOrTrashResolves');

// V-40(c)：`DECLARED_ICON_HAND_DISCARD_BANISH`＝`WXDi-P12-055-E1`（透魔姫　ウリス）【自】：あなたの
// アタックフェイズ開始時、このシグニがアップ状態の場合、対戦相手のシグニ１体を対象とし、あなたの手札を
// １枚選んでもよい。そうした場合、対戦相手は《白》《赤》《青》《緑》《黒》《無》から１つを宣言する。
// あなたはその選んだカードを捨て、そのカードが宣言されたアイコンを持たない場合、それをバニッシュする。
// 🔑CPU（guest）の`opponentResponds`自動応答は**常に選択肢の先頭を選ぶ**（`BattleScreen.tsx:634`
// `inter.options.find(o=>o.available) ?? inter.options[0]`）＝候補順は`['白','赤','青','緑','黒','無']`
// なので**常に《白》を宣言する**。よって捨てる手札の色を選ぶだけで正負の両方を決定論的に作れる
// （実装ソース `execStubPart3.ts:2455`）。
function runDeclaredIconRound(discardCardBase) {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#40200'],
      'field.signi': [['WXDi-P12-055#40201'], null, null],
      'field.signi_down': [false, false, false],
      'field.check': null,
      'hand': [`${discardCardBase}#40202`],
      'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#40210'],
      'field.signi': [['WD01-012#40211'], null, null], // 対象候補（唯一）
      'field.signi_down': [false, false, false],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}
async function driveDeclaredIconRound(page, H, discardCardBase, discardColor) {
  await H.ensureMain();
  let picked = false; let handPicked = false; let declareLog = null;
  for (let s = 0; s < 26; s++) {
    await page.waitForTimeout(800);
    await page.screenshot({ path: `${SHOT}/v40c-${discardCardBase}-${s}.png`, fullPage: true }).catch(() => {});
    // ⚠ログパネルは直近数行しか常時表示しない（「▼」展開が要る）＝出た瞬間に確保しないと後続ログに押し出されて読めなくなる。
    if (!declareLog) declareLog = await H.findLog(/宣言《.》/);
    let did = null;
    if (!did) did = await H.clickTextOrBtn(['アタックフェイズへ']);
    if (!did) {
      const pick0 = page.getByTestId('pick-0').first();
      if (await pick0.count() && await pick0.isVisible().catch(() => false)) {
        const confirmReady = await page.getByRole('button', { name: /決定 \(1\// }).count();
        if (!confirmReady) { await pick0.click().catch(() => {}); did = 'pick:pick-0'; if (!picked) picked = true; else handPicked = true; }
        else { did = await H.clickTextOrBtn(['決定']); }
      }
    }
    if (!did) did = await H.clickTextOrBtn(['発動順序を確定', '確定', 'OK', 'はい']);
    const st = await H.queryState();
    H.log(`  v40c[${s}] -> ${did ?? 'なし'} | picked=${picked} handPicked=${handPicked} declareLog=${declareLog} gField=${JSON.stringify(st?.guest?.fieldSigni)} hHand=${st?.host?.handCards} hTrash=${st?.host?.trashCards} pEff=${st?.pendingEffect ?? '-'}`);
    const resolved = (st?.host?.handCards ?? []).length === 0 && !st?.pendingEffect && picked;
    if (resolved) {
      const declaredColor = declareLog?.match(/宣言《(.)》/)?.[1] ?? null;
      const banished = !(st?.guest?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-012')));
      const expectBanish = declaredColor !== null && declaredColor !== discardColor;
      const consistent = banished === expectBanish;
      return {
        pass: consistent && declaredColor === '白',
        detail: `捨てた札の色=${discardColor}・宣言="${declareLog ?? '-'}"（declared=${declaredColor}）・対象banished=${banished}（期待=${expectBanish}）・gField=${JSON.stringify(st.guest.fieldSigni)}（整合=${consistent}）`,
      };
    }
  }
  const fin = await H.queryState();
  return { pass: false, detail: `未完了（picked=${picked} handPicked=${handPicked} pEff=${fin?.pendingEffect ?? '-'}）` };
}

