// pendingCandidates（実配列＝表示順とは限らない・📌6）からプレフィックス一致するインスタンスの配列indexを
// 割り出して pick-{idx} を押す＝`data-card-num` 属性より確実（同名カードでも instance id で一意）。
async function clickCandidateByPrefix(page, H, st0, prefix, tag) {
  const cands = st0?.pendingCandidates;
  if (!Array.isArray(cands)) return null;
  const idx = cands.findIndex(n => typeof n === 'string' && n.startsWith(prefix));
  if (idx < 0) return null;
  const el = page.getByTestId(`pick-${idx}`).first();
  const cnt = await el.count();
  const vis = cnt ? await el.isVisible().catch(() => false) : false;
  H.log(`    clickCandidateByPrefix(${tag},${prefix}) idx=${idx} count=${cnt} visible=${vis}`);
  if (cnt && vis) {
    await el.click().catch(() => {});
    return `pick-${idx}(${tag}:${prefix})`;
  }
  return null;
}

// V-41(b)：O-32 実装＝`WX16-042-E1`（ＵＮＬＵＣＫＹ）「手札からシグニを１枚捨てる。その後、捨てたシグニと
// 同じレベルの対戦相手のシグニ１体を対象とし、それをバニッシュする。あなたはこの効果をあと２回まで繰り返して
// もよい（合計最大3回）」＝`RepeatAction.optional`（続き501・実装ソース `effectExecutor.ts:4951`）。
// レベルの異なる手札2枚（Lv1/Lv2）を用意し、①各周のBANISH候補が捨てたカードと同レベルの相手シグニ1体だけに
// 絞られること（`pendingCandidates`を直接見る）②「繰り返す」を選ぶと次の周が起きる③最後に「繰り返さない」を
// 選ぶと3周目は起きない（合計2回で打ち切り＝Lv3の相手シグニは無傷で残る）を1本で確認する。
scenarios.v41RepeatOptionalFiltersByLevelAndStops = {
  title: 'V-41(b) WX16-042-E1：各周のバニッシュ候補は捨てたカードと同レベルのみ／「繰り返さない」で打ち切り',
  spec: {
    hostSet: {
      'field.lrig': ['WD01-001#41100'],
      'field.signi': [null, null, null],
      'field.check': null,
      'energy': ['WD03-013#41101'], // 青×1
      'hand': ['WD01-013#41102', 'WD01-012#41103'], // Lv1／Lv2
      'actions_done': [],
    },
    handPrepend: ['WX16-042#41104'],
    guestSet: {
      'field.lrig': ['WD01-001#41110'],
      'field.signi': [['WD01-013#41111'], ['WD01-012#41112'], ['WD01-010#41113']], // Lv1／Lv2／Lv3
      'field.signi_down': [false, false, false],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  },
  async drive(page, H) {
    await H.ensureMain();
    H.log('手札クリック(WX16-042):', await H.clickTestId('my-hand-card-0') ?? '見つからず');
    let energyPicked = false; let castDone = false;
    let discard1 = false; let banish1 = false; let repeatChosen = false;
    let discard2 = false; let banish2 = false; let stopChosen = false;
    let d1Picked = false; let b1Picked = false; let d2Picked = false; let b2Picked = false;
    let candLog = [];
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(800);
      await page.screenshot({ path: `${SHOT}/v41b-${s}.png`, fullPage: true }).catch(() => {});
      const st0 = await H.queryState();
      // pendingCandidates を毎ティック記録（BANISH の絞り込みを直接見る決め手）。
      if (st0?.pendingEffect === 'SELECT_TARGET' && Array.isArray(st0.pendingCandidates)) {
        const key = JSON.stringify(st0.pendingCandidates);
        if (candLog.length === 0 || candLog[candLog.length - 1] !== key) candLog.push(key);
      }
      let did = null;
      if (!castDone) {
        if (!did) did = await H.clickBtn('発動', { exact: true });
        if (!did && !energyPicked) {
          const e0 = page.getByTestId('spellcost-energy-0').first();
          if (await e0.count() && await e0.isVisible().catch(() => false)) { await e0.click().catch(() => {}); did = 'spellcost-energy-0'; energyPicked = true; }
        }
        if (!did && energyPicked) did = await H.clickBtn('発動する', { exact: true });
        if (!(st0?.host?.handCards ?? []).some(n => n?.startsWith('WX16-042'))) castDone = true; // スペル自身が手札から離れた
      } else if (!discard1) {
        if (!d1Picked) { did = await clickCandidateByPrefix(page, H, st0, 'WD01-013', 'hand-d1'); if (did) d1Picked = true; }
        if (!did) did = await H.clickTextOrBtn(['決定']);
        if ((st0?.host?.handCards ?? []).length === 1) discard1 = true;
      } else if (!banish1) {
        if (!b1Picked) { did = await clickCandidateByPrefix(page, H, st0, 'WD01-013', 'banish1'); if (did) b1Picked = true; }
        if (!did) did = await H.clickTextOrBtn(['決定']);
        if (!(st0?.guest?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-013')))) banish1 = true;
      } else if (!repeatChosen) {
        did = await H.clickBtn('繰り返す（残り2回まで）', { exact: true });
        if (did) repeatChosen = true;
      } else if (!discard2) {
        if (!d2Picked) { did = await clickCandidateByPrefix(page, H, st0, 'WD01-012', 'hand-d2'); if (did) d2Picked = true; }
        if (!did) did = await H.clickTextOrBtn(['決定']);
        if ((st0?.host?.handCards ?? []).length === 0) discard2 = true;
      } else if (!banish2) {
        if (!b2Picked) { did = await clickCandidateByPrefix(page, H, st0, 'WD01-012', 'banish2'); if (did) b2Picked = true; }
        if (!did) did = await H.clickTextOrBtn(['決定']);
        if (!(st0?.guest?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-012')))) banish2 = true;
      } else if (!stopChosen) {
        did = await H.clickBtn('繰り返さない', { exact: true });
        if (did) stopChosen = true;
      }
      const st = await H.queryState();
      H.log(`  v41b[${s}] -> ${did ?? 'なし'} | d1=${discard1} b1=${banish1} rep=${repeatChosen} d2=${discard2} b2=${banish2} stop=${stopChosen} cands=${JSON.stringify(st?.pendingCandidates)} gField=${JSON.stringify(st?.guest?.fieldSigni)} hHand=${st?.host?.handCards} pEff=${st?.pendingEffect ?? '-'}`);
      if (stopChosen && !st?.pendingEffect) {
        const gField = st.guest.fieldSigni ?? [];
        const lv1Gone = !gField.some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-013')));
        const lv2Gone = !gField.some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-012')));
        const lv3Kept = gField.some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-010')));
        const handEmpty = (st.host.handCards ?? []).length === 0;
        // 各周のBANISH候補が単一（同レベルだけに絞られている）ことを候補ログから確認。
        const banishCandLogs = candLog.filter(k => k.includes('WD01-013#41111') || k.includes('WD01-012#41112'));
        const filteredOk = banishCandLogs.every(k => JSON.parse(k).length === 1);
        const pass = lv1Gone && lv2Gone && lv3Kept && handEmpty && filteredOk;
        return {
          pass,
          detail: `Lv1消滅=${lv1Gone} Lv2消滅=${lv2Gone} Lv3残置=${lv3Kept} 手札空=${handEmpty}・BANISH候補ログ=${JSON.stringify(banishCandLogs)}（各1件に絞られている=${filteredOk}）`,
        };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（d1=${discard1} b1=${banish1} rep=${repeatChosen} d2=${discard2} b2=${banish2} stop=${stopChosen} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('v41RepeatOptionalFiltersByLevelAndStops');
// ── V-41 END ──

// V-42(a)：O-33 実装＝`WX25-CP1-050-E1`（栗村アイリ）【自】：このシグニがアタックしたとき、あなたの場に他の
// ＜ブルアカ＞のシグニがある場合、次の対戦相手のターンの間、対戦相手は《無》を支払わないかぎり、**中央の**
// シグニゾーンにあるシグニでアタックできない。ゾーン限定banは`signi_attack_bans_this_turn`に`zones:[1]`
// （中央＝ゾーン添字1）で持ち、判定地点でゾーンを引く設計（実装ソース `signiAttackBan.ts:20-31`）。
// host（禁止を受ける側）の3ゾーンにシグニを置き、ban を直接注入して各ゾーンのアタックボタン表示を読む＝
// 中央だけ「アタック（《無》×1）」・左右は無条件「アタック」。
scenarios.v42ZoneLimitedAttackBanCenterOnly = {
  title: 'V-42(a) WX25-CP1-050-E1：中央ゾーンだけ《無》×1のアタック税・左右は無条件（正方向＋対照）',
  spec: {
    hostSet: {
      'field.lrig': ['WD01-001#42000'],
      'field.signi': [['WD01-013#42001'], ['WD01-012#42002'], ['WD01-010#42003']],
      'field.signi_down': [false, false, false],
      'field.check': null,
      'signi_attack_bans_this_turn': [{ zones: [1], unlessPayColorless: 1 }],
      'energy': ['WD01-013#42004'], // 《無》×1を払える最低限（0枚だと支払不能でボタンごと消える＝別の観測になる）
      'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#42010'],
      'field.signi': [null, null, null],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'ATTACK_SIGNI', turn_count: 2 },
  },
  async drive(page, H) {
    const isModalOpen = async () => {
      const tx = page.getByText(/タップ.{0,4}閉じる/).first();
      return await tx.count() > 0 && await tx.isVisible().catch(() => false);
    };
    const ensureClosed = async () => {
      for (let k = 0; k < 6 && await isModalOpen(); k++) {
        await H.closeModals();
        await page.waitForTimeout(300);
      }
    };
    const labels = {};
    for (const zi of [0, 1, 2]) {
      await ensureClosed();
      let opened = false; let label = null;
      for (let s = 0; s < 12 && label === null; s++) {
        await page.waitForTimeout(500);
        await page.screenshot({ path: `${SHOT}/v42a-zone${zi}-${s}.png`, fullPage: true }).catch(() => {});
        if (!opened) { const did = await H.clickTestId(`my-signi-zone-${zi}`); if (did && await isModalOpen()) opened = true; }
        if (opened) {
          const btn = page.locator('[data-testid^="card-action-"][data-action-label^="アタック"]').first();
          const cnt = await btn.count();
          if (cnt && await btn.isVisible().catch(() => false)) {
            label = await btn.getAttribute('data-action-label');
          }
          H.log(`    zone${zi}[${s}] opened=${opened} btnCount=${cnt} body="${(await H.body()).slice(0, 150).replace(/\n/g, ' ')}"`);
        }
      }
      labels[zi] = label;
      H.log(`  v42a zone${zi} -> label="${label}"`);
      await ensureClosed();
    }
    const pass = labels[0] === 'アタック' && labels[1] === 'アタック（《無》×1）' && labels[2] === 'アタック';
    return {
      pass,
      detail: `zone0(左)="${labels[0]}"・zone1(中央)="${labels[1]}"・zone2(右)="${labels[2]}"`,
    };
  },
};
order.push('v42ZoneLimitedAttackBanCenterOnly');
// ── V-42 END ──

// V-43(a)：O-28 実装＝【Ｓランサー】（全角）と engine 側 半角 `Sランサー` の綴りズレ是正（続き503）。
// バトルに勝ち、相手のライフが0枚のとき、Sランサーは相手を敗北させる（通常ランサーは効果消滅するだけ）。
// 旧実装は全角【Ｓランサー】がkeyword判定に一度も当たらず「ランサー」へ格下げされていた（実装ソース
// `BattleScreen.tsx:9309-9319`＝`isSLancer`分岐）。keyword_grantsで直接付与し、ライフ0の相手へ勝利させて
// 「Sランサー：ライフなし → ダメージ → 相手の敗北」ログの有無で正負を対で見る。
function v43aSpec(keyword) {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#43000'],
      'field.signi': [null, ['WD01-010#43001'], null], // 中央＝P10000（Lv3）
      'field.signi_down': [false, false, false],
      'field.check': null,
      'keyword_grants': { 'WD01-010#43001': [keyword] },
      'energy': [], 'hand': [], 'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#43010'],
      'field.signi': [null, ['WD01-013#43011'], null], // 正面＝P3000（Lv1）＝確実に負ける
      'field.signi_down': [false, false, false],
      'field.check': null,
      'life_cloth': [], // ライフ0枚
      'hand': [], // ガード候補なし
    },
    top: { active: 'host', turn_phase: 'ATTACK_SIGNI', turn_count: 2 },
  };
}
async function driveV43a(page, H, keyword) {
  H.log(`手札シグニゾーン1クリック(${keyword}):`, await H.clickTestId('my-signi-zone-1') ?? '見つからず');
  let attacked = false;
  for (let s = 0; s < 20; s++) {
    await page.waitForTimeout(700);
    await page.screenshot({ path: `${SHOT}/v43a-${keyword}-${s}.png`, fullPage: true }).catch(() => {});
    let did = null;
    if (!attacked) {
      const atk = page.locator('[data-testid^="card-action-"][data-action-label^="アタック"]').first();
      if (await atk.count() && await atk.isVisible().catch(() => false) && await atk.isEnabled().catch(() => false)) {
        await atk.click({ timeout: 1500 }).catch(() => {}); did = 'action:アタック'; attacked = true;
      }
    }
    if (!did) did = await H.clickTextOrBtn(['ガードしない', 'しない', 'OK', '決定']);
    const st = await H.queryState();
    H.log(`  v43a[${s}] -> ${did ?? 'なし'} | attacked=${attacked} gLife=${st?.guest?.life} pEff=${st?.pendingEffect ?? '-'}`);
    if (attacked) {
      const winLog = await H.findLog(/Sランサー：ライフなし → ダメージ → 相手の敗北/);
      const fizzleLog = await H.findLog(/ランサー：ライフなし（効果消滅）/);
      if (winLog || fizzleLog) {
        return {
          pass: keyword === 'Sランサー' ? !!winLog : (!!fizzleLog && !winLog),
          detail: `keyword=${keyword}・勝利ログ="${winLog ?? '-'}"・消滅ログ="${fizzleLog ?? '-'}"`,
        };
      }
    }
  }
  return { pass: false, detail: `未完了（attacked=${attacked}）` };
}

scenarios.v43SLancerDefeatsOpponentAtZeroLife = {
  title: 'V-43(a) 【Ｓランサー】：勝利＋相手ライフ0枚→相手を敗北させる',
  spec: v43aSpec('Sランサー'),
  async drive(page, H) { return driveV43a(page, H, 'Sランサー'); },
};

scenarios.v43RegularLancerFizzlesAtZeroLife = {
  title: 'V-43(a)対照 【ランサー】：勝利＋相手ライフ0枚→効果消滅（敗北させない）',
  spec: v43aSpec('ランサー'),
  async drive(page, H) { return driveV43a(page, H, 'ランサー'); },
};
order.push('v43SLancerDefeatsOpponentAtZeroLife', 'v43RegularLancerFizzlesAtZeroLife');
// ── V-43 END ──

// V-44(a)：O-5 実装＝`WX16-Re18-E1`（レゾナンス・マーチ）「あなたのルリグデッキからレゾナを２枚まで
// 出現条件を無視して場に出す。この方法で場に出たレゾナの【出】能力は発動しない。」＝`SUMMON_RESONA_FROM_LRIG_DECK`
// （実装ソース `execStubPart3.ts:2991`）。旧実装は候補1枚固定（`candidates[0]`）だったため「２枚まで」の
// 複数選択が効くこと（＝2枚とも場に出る）を実機で確認する。
// 🔴実機で新規バグ発見（続き584・4回中2回再現＝約50%の間欠バグ）＝1枚目をSELECT_SIGNI_ZONEで配置した直後、
// `INTERNAL_PLACE_SUMMONED_RESONAS`の継続（`execStubPart3.ts:3043-3054`＝空きゾーンが1つに減った場合は
// 対話を挟まず自動配置する分岐）が**発火せず2枚目がルリグデッキに取り残される**ことがある（`pendingEffect`は
// 正常に`-`へ戻り、UIは「完了した」ように見えるが実際には2枚目が場に出ていない＝黙って消えたわけではなく
// ルリグデッキに残るが、原文の「２枚まで」を満たせていない過少実行）。詳細はBUGFIXES参照。
scenarios.v44SummonTwoResonasFromLrigDeck = {
  title: 'V-44(a) WX16-Re18-E1：ルリグデッキから「２枚まで」選ぶと2枚とも場に出る（🔴間欠バグあり・4回中2回再現）',
  spec: {
    hostSet: {
      'field.lrig': ['WD01-001#44000'],
      'field.signi': [['WD01-013#44007'], null, null], // zone0にfiller・空きは2ゾーン
      'field.signi_down': [false, false, false],
      'field.check': null,
      'lrig_deck': ['WX16-Re18#44001', 'WX08-008#44002', 'WX08-008#44003'],
      'energy': ['WD01-013#44004', 'WD01-013#44005', 'WD01-012#44006'], // 白・白・無払い用
      'hand': [], 'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#44010'],
      'field.signi': [null, null, null],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  },
  async drive(page, H) {
    await H.ensureMain();
    const before = await H.queryState();
    H.log('開始時 host.lrigDeck:', before?.host?.lrigDeckCards);
    H.log('ルリグDK:', await H.clickTestId('my-lrig-dk') ?? '見つからず');
    let e0 = false; let e1 = false; let e2 = false; let castDone = false;
    let p0 = false; let p1 = false; let picked = false;
    let zonesPlaced = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(800);
      await page.screenshot({ path: `${SHOT}/v44a-${s}.png`, fullPage: true }).catch(() => {});
      let did = null;
      if (!castDone) {
        if (!did && !e0) { const el = page.getByTestId('artscost-energy-0').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e0'; e0 = true; } }
        if (!did && e0 && !e1) { const el = page.getByTestId('artscost-energy-1').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e1'; e1 = true; } }
        if (!did && e1 && !e2) { const el = page.getByTestId('artscost-energy-2').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e2'; e2 = true; } }
        if (!did && e2) did = await H.clickBtn('アーツ使用', { exact: false });
        if (!did) did = await H.clickTextOrBtn(['使用']);
        if (!did) did = await H.clickTestId('zone-card-0');
        const st0 = await H.queryState();
        if ((st0?.host?.lrigDeckCards ?? []).length < (before?.host?.lrigDeckCards ?? []).length) castDone = true;
      } else if (!picked) {
        const st0 = await H.queryState();
        if (!p0 && Array.isArray(st0?.pendingCandidates) && st0.pendingCandidates.length >= 1) {
          const el = page.getByTestId('pick-0').first();
          if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'pick-0'; p0 = true; }
        }
        if (!did && p0 && !p1) {
          const el = page.getByTestId('pick-1').first();
          if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'pick-1'; p1 = true; }
        }
        if (!did && p0 && p1) {
          // ⚠**押す前に「決定 (n/2)」を読む**（Opusタスク12(cxlvi)）＝選択が2枚そろっていない状態で
          //   押すと `upTo` のこの効果は 1枚でも確定でき、「2枚まで選んだのに1枚しか出ない」FAIL を
          //   「間欠バグ」に見せてしまう。ラベルを記録しておけば原因が一目で分かる。
          const cb = page.getByRole('button', { name: /^決定/ }).first();
          const cLabel = (await cb.count()) ? (await cb.innerText().catch(() => '')).replace(/\s+/g, '') : '(なし)';
          H.log('  決定ラベル:', cLabel);
          if (!/\(2\/2\)/.test(cLabel)) {
            // 選択が欠けている＝クリックが1回落ちた。押さずに選び直す（次ループで pick を再試行）。
            H.log('  🔴選択が2枚そろっていないので押さずに再選択する');
            p0 = false; p1 = false;
          } else {
            did = await H.clickTextOrBtn(['決定']); if (did) picked = true;
          }
        }
      } else {
        did = await H.clickZone();
        if (did) zonesPlaced++;
        if (!did) did = await H.stdStep();
      }
      const st = await H.queryState();
      H.log(`  v44a[${s}] -> ${did ?? 'なし'} | castDone=${castDone} p0=${p0} p1=${p1} picked=${picked} zonesPlaced=${zonesPlaced} hField=${JSON.stringify(st?.host?.fieldSigni)} hLrigDeck=${JSON.stringify(st?.host?.lrigDeckCards)} pEff=${st?.pendingEffect ?? '-'} stackQueue=${JSON.stringify(st?.stackQueue)}`);
      const resonaCount = (st?.host?.fieldSigni ?? []).filter(z => Array.isArray(z) && z.some(n => n?.startsWith('WX08-008'))).length;
      if (picked && resonaCount >= 2 && !st?.pendingEffect) {
        return {
          pass: resonaCount === 2,
          detail: `場に出たレゾナ数=${resonaCount}（期待2）・hField=${JSON.stringify(st.host.fieldSigni)}`,
        };
      }
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（castDone=${castDone} picked=${picked} zonesPlaced=${zonesPlaced} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('v44SummonTwoResonasFromLrigDeck');

// Opusタスク12(cxlvi)＝「２枚まで選んだのに1枚しか出ない」の再現プローブ。
// 仮説＝**選択中に無関係な battle_states の更新が届くと、複数枚選択が黙って全部消える**
//   （`BattleScreen.tsx` の「pending_effect が変わったら選択をリセット」useEffect が
//    `bs?.pending_effect` の**オブジェクト同一性**を deps にしており、realtime は毎回
//    新しいオブジェクトを渡すので、内容が同じでもリセットが走る）。
// 手順＝pick-0 を選ぶ →「決定 (1/2)」を読む → **同値の turn_count を書き戻すだけの行更新**を投げる →
//   もう一度ラベルを読む。**選択が生き残っていれば PASS**（修正前は (0/2) に戻る＝FAIL）。
scenarios.v44SelectionSurvivesUnrelatedStateUpdate = {
  title: 'V-44(a) 追加：複数枚選択中に無関係な盤面更新が来ても選択が消えない（Opusタスク12(cxlvi)）',
  spec: scenarios.v44SummonTwoResonasFromLrigDeck.spec,
  async drive(page, H) {
    await H.ensureMain();
    H.log('ルリグDK:', await H.clickTestId('my-lrig-dk') ?? '見つからず');
    const before = await H.queryState();
    let e0 = false; let e1 = false; let e2 = false; let castDone = false;
    for (let s = 0; s < 20 && !castDone; s++) {
      await page.waitForTimeout(700);
      let did = null;
      if (!did && !e0) { const el = page.getByTestId('artscost-energy-0').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e0'; e0 = true; } }
      if (!did && e0 && !e1) { const el = page.getByTestId('artscost-energy-1').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e1'; e1 = true; } }
      if (!did && e1 && !e2) { const el = page.getByTestId('artscost-energy-2').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e2'; e2 = true; } }
      if (!did && e2) did = await H.clickBtn('アーツ使用', { exact: false });
      if (!did) did = await H.clickTextOrBtn(['使用']);
      if (!did) did = await H.clickTestId('zone-card-0');
      const st = await H.queryState();
      if (st?.pendingEffect === 'SELECT_TARGET') castDone = true;
      H.log(`  probe-cast[${s}] -> ${did ?? 'なし'} | pEff=${st?.pendingEffect ?? '-'} hLrigDeck=${JSON.stringify(st?.host?.lrigDeckCards)}`);
    }
    if (!castDone) return { pass: false, detail: 'SELECT_TARGET まで到達しなかった（アーツ使用に失敗）' };
    const confirmLabel = async () => {
      const b = page.getByRole('button', { name: /^決定/ }).first();
      if (!(await b.count())) return '(決定ボタンなし)';
      return (await b.innerText().catch(() => '')).replace(/\s+/g, '');
    };
    const pick0 = page.getByTestId('pick-0').first();
    let pickReady = false;
    for (let k = 0; k < 10 && !pickReady; k++) {
      await page.waitForTimeout(500);
      pickReady = (await pick0.count()) > 0 && await pick0.isVisible().catch(() => false);
    }
    if (!pickReady) return { pass: false, detail: 'pick-0 が出ていない' };
    await pick0.click();
    await page.waitForTimeout(400);
    const l1 = await confirmLabel();
    H.log('  選択直後のラベル:', l1);
    // 無関係な行更新＝turn_count を**同じ値**で書き戻すだけ（盤面は1ビットも変えない）。
    const patched = await page.evaluate(async ({ SUPA_URL, ANON }) => {
      const key = Object.keys(localStorage).find(k => /^sb-.*-auth-token$/.test(k));
      const sess = JSON.parse(localStorage.getItem(key)); const token = sess.access_token; const uid = sess.user?.id;
      const h = { apikey: ANON, Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
      const r1 = await fetch(`${SUPA_URL}/rest/v1/rooms?host_id=eq.${uid}&status=eq.PLAYING&select=id`, { headers: h });
      const roomId = (await r1.json())?.[0]?.id; if (!roomId) return { error: 'PLAYINGルームなし' };
      const r2 = await fetch(`${SUPA_URL}/rest/v1/battle_states?room_id=eq.${roomId}&select=turn_count`, { headers: h });
      const turnCount = (await r2.json())?.[0]?.turn_count;
      const r3 = await fetch(`${SUPA_URL}/rest/v1/battle_states?room_id=eq.${roomId}`, {
        method: 'PATCH', headers: h, body: JSON.stringify({ turn_count: turnCount }),
      });
      return { ok: r3.ok, status: r3.status, turnCount };
    }, { SUPA_URL, ANON });
    H.log('  無関係な行更新:', JSON.stringify(patched));
    await page.waitForTimeout(1800);
    const l2 = await confirmLabel();
    H.log('  行更新後のラベル:', l2);
    const kept = l1 === l2 && /\(1\/2\)/.test(l2);
    return {
      pass: kept,
      detail: kept
        ? `選択が維持された（${l1} → ${l2}）`
        : `🔴選択が消えた（${l1} → ${l2}）＝無関係な battle_states 更新で effectSelectedNums がリセットされている`,
    };
  },
};
order.push('v44SelectionSurvivesUnrelatedStateUpdate');
// ── V-44 END ──

// V-20：`WXDi-P10-039-E2`（蒼魔姫　リッチレーサー）「このカードが捨てられたとき、手札を１枚捨ててもよい。
// そうした場合、そのターン終了時、《青》《無》を支払ってもよい。そうした場合、このカードをトラッシュから
// 場に出す。」＝二段の任意コスト。⚠**Opusタスク12(cxli)＝手札上限超過のターン終了時捨て札
// （`confirmEndDiscard`）はON_TRASH系トリガーを一切収集しない未修正バグの経路を踏むと発火しない**ため、
// 代わりに`WX16-042-E1`（ＵＮＬＵＣＫＹ）の「手札からシグニを１枚捨てる」TRASHアクション（central diff
// 経由＝正しく発火する）でこのカードを捨てさせる経路に迂回する（PLAN §7 V-20 の迂回方針どおり）。
function v20Spec() {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#45000'],
      'field.signi': [['WD01-013#45001'], null, null], // zone0にfiller・空きは2ゾーン（ADD_TO_FIELD用）
      'field.signi_down': [false, false, false],
      'field.check': null,
      'energy': ['WD03-013#45002', 'WD03-013#45003', 'WD01-013#45004'], // 青・青・白（スペル代1＋②のコスト青無）
      'hand': ['WXDi-P10-039#45005', 'WX19-064#45006'], // 捨てる対象（シグニ）／①のコスト用ダミー（非シグニ）
      'actions_done': [],
    },
    handPrepend: ['WX16-042#45007'],
    guestSet: {
      'field.lrig': ['WD01-001#45010'],
      'field.signi': [['WD01-010#45011'], null, null], // Lv3・WX16-042②のバニッシュ対象
      'field.signi_down': [false, false, false],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}
// 🆕(cl・続き591)＝MAIN から END まで進める。フェイズ進行ボタンのラベルは
// `src/screens/battle/uiConstants.ts` の `PHASE_BTN` でフェイズごとに変わる（`ターン終了` は END でしか出ない）。
// ⚠1つのラベルだけを叩く旧実装だと MAIN で何も押せず「未完了」で落ちる（続き591 で実際に踏んだ）。
const V20_PHASE_BTNS = ['アタックフェイズへ', 'アーツ終了→相手へ', 'アーツ終了', 'ルリグアタックへ', 'エンドフェイズへ', 'ターン終了'];
// ⚠フェイズ進行の途中に確認ダイアログが挟まる（「まだ攻撃していないシグニがいます→このまま進む」等）。
//   モーダルが出ている間は進行ボタンのクリックが**タイムアウトする**ので、確認ダイアログを先に捌く。
const V20_CONFIRM_BTNS = ['このまま進む', '進む', 'ガードしない', 'OK', 'はい'];
async function advancePhaseV20(H) {
  for (const label of V20_CONFIRM_BTNS) {
    const did = await H.clickBtn(label, { exact: true });
    if (did) return did;
  }
  for (const label of V20_PHASE_BTNS) {
    const did = await H.clickBtn(label, { exact: true });
    if (did) return did;
  }
  return null;
}

async function driveV20(page, H, payBoth) {
  await H.ensureMain();
  H.log('手札クリック(WX16-042):', await H.clickTestId('my-hand-card-0') ?? '見つからず');
  let energyPicked = false; let castDone = false;
  let discardPicked = false; let discarded = false;
  let banishPicked = false; let banished = false;
  let step1Chosen = false; let step1PayPicked = false; let step1PayCandPicked = false;
  let step2Chosen = false; let step2E0 = false; let step2E1 = false; let step2Confirmed = false;
  let zoned = false;
  // 🆕(cl・続き591)＝原文「そうした場合、**そのターン終了時**、②《青》《無》を支払ってもよい」＝
  //   ①を払っても②はその場では出ず、**ターン終了時の遅延トリガー**で出る。
  //   `preEndPending`/`preEndOnField` は「①直後に即時解決していないこと」＝(cl) の回帰ガード。
  let preEndChecked = false; let preEndPending = null; let preEndOnField = null;
  let fired = false; let endClicks = 0; let sawPendingAfterSkip = false; let turnEnded = false;
  const onFieldNow = st => (st?.host?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WXDi-P10-039')));
  for (let s = 0; s < 44; s++) {
    await page.waitForTimeout(700);
    await page.screenshot({ path: `${SHOT}/v20-${payBoth}-${s}.png`, fullPage: true }).catch(() => {});
    const st0 = await H.queryState();
    let did = null;
    if (!castDone) {
      if (!did) did = await H.clickBtn('発動', { exact: true });
      if (!did && !energyPicked) { const el = page.getByTestId('spellcost-energy-0').first(); if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'spellcost-energy-0'; energyPicked = true; } }
      if (!did && energyPicked) did = await H.clickBtn('発動する', { exact: true });
      if (!(st0?.host?.handCards ?? []).some(n => n?.startsWith('WX16-042'))) castDone = true;
    } else if (!discarded) {
      if (!discardPicked) { did = await clickCandidateByPrefix(page, H, st0, 'WXDi-P10-039', 'discard'); if (did) discardPicked = true; }
      if (!did) did = await H.clickTextOrBtn(['決定']);
      if (!(st0?.host?.handCards ?? []).some(n => n?.startsWith('WXDi-P10-039'))) discarded = true;
    } else if (!banished) {
      if (!banishPicked) { did = await clickCandidateByPrefix(page, H, st0, 'WD01-010', 'banish'); if (did) banishPicked = true; }
      if (!did) did = await H.clickTextOrBtn(['決定']);
      if (!(st0?.guest?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WD01-010')))) banished = true;
    } else if (await page.getByRole('button', { name: '繰り返さない', exact: true }).count()) {
      // WX16-042自身のREPEAT.optional（V-41(b)と同型）＝バニッシュ確定後に必ず1回出る。
      // このシナリオでは1回で十分＝毎回「繰り返さない」で打ち切ってWXDi-P10-039のON_TRASHへ進む。
      did = await H.clickBtn('繰り返さない', { exact: true });
    } else if (!step1Chosen) {
      did = await H.clickTestId(payBoth ? 'optcost-pay' : 'optcost-skip');
      if (did) step1Chosen = true;
    } else if (payBoth && !step1PayPicked) {
      // ①のコスト＝手札1枚を捨てる（残っているのはWX19-064のみ）。ピック後も「決定」が必要＝
      // hand が実際に空になるまで（＝支払いが確定するまで）このブランチに留まる。
      if (!step1PayCandPicked) { did = await clickCandidateByPrefix(page, H, st0, 'WX19-064', 'step1pay'); if (did) step1PayCandPicked = true; }
      if (!did) did = await H.clickTextOrBtn(['決定']);
      if ((st0?.host?.handCards ?? []).length === 0) step1PayPicked = true;
    } else if (!payBoth && step1Chosen) {
      // 🆕(cl)＝①をスキップしたら**予約自体が設置されない**＝ターン終了を跨いでも②は出ない。
      //   ここまで見ないと「その場で②が出ないだけ」と区別できない（旧シナリオはそこで打ち切っていた）。
      // ⚠**「pending が出た」だけでは判定にならない**＝ターンが相手へ渡れば無関係な pending が普通に出る。
      //   ②の提示（任意コストの pay ボタン）か、③の対象（この効果元）が候補に出たときだけを異常とみなす。
      if ((st0?.pendingCandidates ?? []).some(n => n?.startsWith('WXDi-P10-039'))) sawPendingAfterSkip = true;
      if (await page.getByTestId('optcost-pay').first().count()
          && await page.getByTestId('optcost-pay').first().isVisible().catch(() => false)) sawPendingAfterSkip = true;
      // ⚠**実際に END を跨ぐまで**進める（「ターン終了」ボタンは END フェイズでしか出ない）＝
      //   途中のフェイズで打ち切ると「その場で②が出ないだけ」しか見ていないことになる。
      if (!turnEnded || endClicks < 8) {
        did = await advancePhaseV20(H);
        if (did) endClicks++;
        if (did === 'btn:ターン終了') turnEnded = true;
      }
    } else if (payBoth && !fired) {
      // 🆕(cl)＝①を払った直後は**何も出ない**（予約されただけ）。ターン終了まで進めて②を出させる。
      if (!preEndChecked) {
        preEndPending = st0?.pendingEffect ?? '-';
        preEndOnField = onFieldNow(st0);
        preEndChecked = true;
        H.log(`    (cl)①pay直後の観測: pEff=${preEndPending} 場に復帰済み=${preEndOnField}（どちらも「出ていない」が正）`);
      }
      if (st0?.pendingEffect) { fired = true; H.log(`    (cl)ターン終了時に②が発火（ターン終了クリック${endClicks}回）`); }
      else {
        did = await advancePhaseV20(H);
        if (did) endClicks++;
      }
    } else if (payBoth && !step2E0) {
      const el = page.getByTestId('optcost-energy-0').first();
      if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'optcost-energy-0'; step2E0 = true; }
    } else if (payBoth && !step2E1) {
      const el = page.getByTestId('optcost-energy-1').first();
      if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'optcost-energy-1'; step2E1 = true; }
    } else if (payBoth && !step2Confirmed) {
      const el = page.getByTestId('optcost-pay').first();
      if (await el.count() && await el.isVisible().catch(() => false) && await el.isEnabled().catch(() => false)) { await el.click().catch(() => {}); did = 'optcost-pay(confirm)'; step2Confirmed = true; }
    } else if (payBoth) {
      did = await H.clickZone();
      if (did) zoned = true;
      if (!did) did = await H.stdStep();
    }
    const st = await H.queryState();
    H.log(`  v20[${s}] -> ${did ?? 'なし'} | payBoth=${payBoth} discarded=${discarded} banished=${banished} step1=${step1Chosen} step2=${step2Chosen} zoned=${zoned} hHand=${st?.host?.handCards} hTrash=${st?.host?.trashCards} hField=${JSON.stringify(st?.host?.fieldSigni)} pEff=${st?.pendingEffect ?? '-'}`);
    if (!payBoth && step1Chosen && turnEnded && endClicks >= 8 && !st?.pendingEffect) {
      const inTrash = (st.host.trashCards ?? []).some(n => n?.startsWith('WXDi-P10-039'));
      const onField = (st.host.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WXDi-P10-039')));
      return {
        pass: inTrash && !onField && !sawPendingAfterSkip,
        detail: `①スキップ→ターン終了を跨いでも②は出ない＝トラッシュに残置=${inTrash}・場に無い=${!onField}・skip後に②の提示/③の対象が出た=${sawPendingAfterSkip}（(cl) 予約非設置の確認・END到達=${turnEnded}・進行${endClicks}回）・hHand=${JSON.stringify(st.host.handCards)}`,
      };
    }
    // 🔴①をスキップしたのに②を飛ばして③（ADD_TO_FIELD）のSELECT_TARGETが出た＝実バグ確認。
    if (!payBoth && step1Chosen && st?.pendingEffect === 'SELECT_TARGET'
        && (st.pendingCandidates ?? []).some(n => n?.startsWith('WXDi-P10-039'))) {
      return {
        pass: false,
        detail: `🔴実バグ確認＝①「スキップ」を選んだのに②《青》《無》の支払い提示を飛ばして③「トラッシュから場に出す」のSELECT_TARGETが出た（candidates=${JSON.stringify(st.pendingCandidates)}）＝「そうした場合」の入れ子ゲートが engine 側で外れている（詳細はBUGFIXES参照）`,
      };
    }
    if (payBoth && zoned && !st?.pendingEffect) {
      const onField = (st.host.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WXDi-P10-039')));
      const inTrash = (st.host.trashCards ?? []).some(n => n?.startsWith('WXDi-P10-039'));
      // 🆕(cl)＝「①直後には出ず、ターン終了時に出た」ことまで合格条件に含める（即時解決への退行ガード）。
      const deferred = preEndPending === '-' && preEndOnField === false && endClicks > 0;
      return {
        pass: onField && !inTrash && deferred,
        detail: `①②とも支払い＝場に復帰=${onField}・トラッシュに残っていない=${!inTrash}・(cl)①直後は未解決=${deferred}（pEff=${preEndPending} 場=${preEndOnField} ターン終了${endClicks}回で②が発火）・hField=${JSON.stringify(st.host.fieldSigni)}`,
      };
    }
  }
  const fin = await H.queryState();
  return { pass: false, detail: `未完了（discarded=${discarded} banished=${banished} step1=${step1Chosen} step2=${step2Chosen} zoned=${zoned} pEff=${fin?.pendingEffect ?? '-'}）` };
}

scenarios.v20DiscardSkipFirstBlocksSecond = {
  title: 'V-20 WXDi-P10-039-E2：①をスキップすると②は出ない（カードはトラッシュに残置）',
  spec: v20Spec(),
  async drive(page, H) { return driveV20(page, H, false); },
};

scenarios.v20DiscardPayBothReturnsToField = {
  title: 'V-20対照 WXDi-P10-039-E2：①②とも支払うとトラッシュから場に復帰する',
  spec: v20Spec(),
  async drive(page, H) { return driveV20(page, H, true); },
};
order.push('v20DiscardSkipFirstBlocksSecond', 'v20DiscardPayBothReturnsToField');
// ── V-20 END ──

// V-30：ターン境界を跨いだ能力喪失（続き453＝`REMOVE_ABILITIES.until`）。
// ⚠続き566の実測どおり `turn_phase:'END'` を直接注入すると room 正規化時に既にターン終端の失効処理が
// 走ってしまい観測が壊れる（設計限界・室注入の見直しが要る＝未着手のまま）。今回は**READ側**＝
// `abilities_removed` に積まれている間、実際に host 自身の【起】ボタンが UI から消えるかを直接検証する
// （`signiActivateGate.ts:66`＝`my.abilities_removed?.includes(topNum)` なら候補ごと0件）。
// `UNTIL_OPP_TURN_END`/`NEXT_TURN` の2スロット予約が正しく`abilities_removed`へ昇格することを実機の
// ターン進行で確認する部分（真のターン境界越え）は引き続き未着手＝follow-up。
function v30Spec(suppress) {
  return {
    hostSet: {
      'field.lrig': ['WD01-001#46000'],
      'field.signi': [['WX02-044#46001'], null, null], // 大罪の所以 バアル（【起】《ダウン》：デッキ上公開）
      'field.signi_down': [false, false, false],
      'field.check': null,
      'abilities_removed': suppress ? ['WX02-044#46001'] : [],
      'energy': [], 'hand': [], 'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#46010'],
      'field.signi': [null, null, null],
      'field.check': null,
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}
async function driveV30(page, H, suppress) {
  let opened = false; let found = null;
  for (let s = 0; s < 14 && found === null; s++) {
    await page.waitForTimeout(500);
    await page.screenshot({ path: `${SHOT}/v30-${suppress}-${s}.png`, fullPage: true }).catch(() => {});
    if (!opened) { const did = await H.clickTestId('my-signi-zone-0'); if (did) opened = true; }
    if (opened) {
      const btn = page.locator('[data-testid^="card-action-"][data-action-label*="起"]').first();
      found = (await btn.count()) > 0 ? true : (found === null && s >= 3 ? false : null);
    }
  }
  H.log(`  v30 suppress=${suppress} -> 【起】ボタン検出=${found}`);
  return {
    pass: suppress ? found === false : found === true,
    detail: `abilities_removed注入=${suppress}・【起】ボタン検出=${found}（期待=${suppress ? false : true}）`,
  };
}

scenarios.v30AbilityRemovedSuppressesActivated = {
  title: 'V-30 abilities_removed：積まれている間【起】ボタンがUIから消える',
  spec: v30Spec(true),
  async drive(page, H) { return driveV30(page, H, true); },
};

scenarios.v30AbilityRemovedControlShowsActivated = {
  title: 'V-30対照 abilities_removed空：【起】ボタンは通常どおり表示される',
  spec: v30Spec(false),
  async drive(page, H) { return driveV30(page, H, false); },
};
order.push('v30AbilityRemovedSuppressesActivated', 'v30AbilityRemovedControlShowsActivated');
// ── V-30 END ──

// V-45(a)：O-6/O-7 実装＝`WX25-P2-058-E1`（参ノ遊姫　ベイゴマ）【自】：このシグニがアタックしたとき、
// そのアタック終了時、あなたの場に《アイヤイ★クイーン》がいる場合、あなたのエナゾーンからレベル２以下の
// ＜遊具＞のシグニ１枚を対象とし、《緑》《緑》《無》を支払ってもよい。そうした場合、それと場にあるこのシグニ
// の場所を入れ替える。JSONは`CONDITIONAL{HAS_CARD_IN_FIELD}{then:STUB(OPTIONAL_COST)}`という「包み形」
// （実装ソース `effectExecutor.ts:3837-3867`＝ゲート不成立ならコストも本体も丸ごと読み飛ばす）に続けて
// `CONDITIONAL(IS_MY_TURN){REARRANGE_SIGNI,swap}`が単純に1段だけ続く構造＝V-20で見つかった「二段連鎖」の
// バグは踏まない形。《アイヤイ★クイーン》の有無で正負を対で見る。
function v45aSpec(hasQueen) {
  return {
    hostSet: {
      'field.lrig': [hasQueen ? 'WX25-P2-026#47000' : 'WD01-001#47000'],
      'field.signi': [null, ['WX25-P2-058#47001'], null], // 中央＝参ノ遊姫ベイゴマ
      'field.signi_down': [false, false, false],
      'field.check': null,
      'energy': ['WD04-013#47002', 'WD04-013#47003', 'WD01-013#47004', 'WX24-P2-074#47005'], // 緑・緑・白（無）・スワップ対象（遊具Lv1）
      'hand': [], 'actions_done': [],
    },
    guestSet: {
      'field.lrig': ['WD01-001#47010'],
      // 正面に弱いシグニを置く＝直接ライフアタックにすると「相手のライフクロスクラッシュ」確認モーダルが
      // 割り込み、CPU応答待ちで長時間ハングする（続き586実測）。シグニ戦にして直接ダメージを避ける。
      'field.signi': [null, ['WD01-013#47012'], null],
      'field.signi_down': [false, false, false],
      'field.check': null,
      'hand': [],
      'life_cloth': ['WD01-013#47020', 'WD01-013#47021'],
    },
    top: { active: 'host', turn_phase: 'ATTACK_SIGNI', turn_count: 2 },
  };
}
async function driveV45a(page, H, hasQueen) {
  let attacked = false; let zoneOpened = false;
  let e0 = false; let e1 = false; let e2 = false;
  let picked = false; let confirmed = false;
  for (let s = 0; s < 26; s++) {
    await page.waitForTimeout(700);
    await page.screenshot({ path: `${SHOT}/v45a-${hasQueen}-${s}.png`, fullPage: true }).catch(() => {});
    const st0 = await H.queryState();
    let did = null;
    if (!attacked) {
      if (!zoneOpened) { const did2 = await H.clickTestId('my-signi-zone-1'); if (did2) { did = did2; zoneOpened = true; } }
      if (!did) {
        const atk = page.locator('[data-testid^="card-action-"][data-action-label^="アタック"]').first();
        if (await atk.count() && await atk.isVisible().catch(() => false) && await atk.isEnabled().catch(() => false)) {
          await atk.click({ timeout: 1500 }).catch(() => {}); did = 'action:アタック'; attacked = true;
        }
      }
      if (!did) did = await H.clickTextOrBtn(['ガードしない', 'しない', 'OK', '決定']);
    } else if (hasQueen && !e0 && !e1 && !e2) {
      const el = page.getByTestId('optcost-energy-0').first();
      if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e0'; e0 = true; }
    } else if (hasQueen && e0 && !e1) {
      const el = page.getByTestId('optcost-energy-1').first();
      if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e1'; e1 = true; }
    } else if (hasQueen && e1 && !e2) {
      const el = page.getByTestId('optcost-energy-2').first();
      if (await el.count() && await el.isVisible().catch(() => false)) { await el.click().catch(() => {}); did = 'e2'; e2 = true; }
    } else if (hasQueen && e2) {
      const el = page.getByTestId('optcost-pay').first();
      if (await el.count() && await el.isVisible().catch(() => false) && await el.isEnabled().catch(() => false)) { await el.click().catch(() => {}); did = 'optcost-pay'; }
      if (!did && !picked) { const p = await clickCandidateByPrefix(page, H, st0, 'WX24-P2-074', 'swap'); if (p) { did = p; picked = true; } }
      if (!did && picked && !confirmed) { did = await H.clickTextOrBtn(['決定']); if (did) confirmed = true; }
      // REARRANGE_SIGNI（mode:'swap'）＝カード画像ボタンに data-testid が無いので alt テキストで狙う。
      if (!did && confirmed) { did = await H.clickModalImage('参ノ遊姫　ベイゴマ'); }
    } else if (!hasQueen) {
      did = await H.clickTextOrBtn(['スキップ', '決定', 'OK']);
    }
    const st = await H.queryState();
    H.log(`  v45a[${s}] -> ${did ?? 'なし'} | hasQueen=${hasQueen} attacked=${attacked} e0=${e0} e1=${e1} e2=${e2} picked=${picked} confirmed=${confirmed} hField=${JSON.stringify(st?.host?.fieldSigni)} hEnergy=${st?.host?.energyCards} pEff=${st?.pendingEffect ?? '-'}`);
    const swapped = (st?.host?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WX24-P2-074')));
    const stayed = (st?.host?.fieldSigni ?? []).some(z => Array.isArray(z) && z.some(n => n?.startsWith('WX25-P2-058')));
    if (attacked && !st?.pendingEffect && (hasQueen ? (confirmed || swapped) : true) && s >= 6) {
      return {
        pass: hasQueen ? (swapped && !stayed) : (stayed && !swapped),
        detail: `hasQueen=${hasQueen}・スワップ後の場=${JSON.stringify(st.host.fieldSigni)}・エナ=${JSON.stringify(st.host.energyCards)}（期待swapped=${hasQueen}）`,
      };
    }
  }
  const fin = await H.queryState();
  return { pass: false, detail: `未完了（attacked=${attacked} picked=${picked} confirmed=${confirmed} pEff=${fin?.pendingEffect ?? '-'}）` };
}

