    return { pass: false, detail: `候補未観測（opened=${opened} summoned=${summoned} zoned=${zoned} cost=${costPicked} fired=${fired} hField=${JSON.stringify(fin?.host?.fieldSigni)} pEff=${fin?.pendingEffect ?? '-'}）` };
