// ── O-54（2026-08-24）＝「この(シグニ|カード)を**エナゾーンから**〜」＝バニッシュでエナへ行った**自分自身** ──
// 🔴parser がこの語を読まず、`ADD_TO_FIELD` は `filter:{cardType:'シグニ'}` だけ＝**エナのどのシグニでも
//   出せる過剰実行**、`ADD_TO_LIFE` は `fromTop:true`＝**デッキの一番上**に落ちていた（実測15効果）。
//   受け皿（`TargetFilter.thisCardOnly` ＋ 各 exec の ENERGY_CARD 分岐）は engine に在り、**未配線**だった。
// 🔑**gates では守れない層**＝逆翻訳／golden／census は「JSON がどうか」しか見ない。実機の観測点は
//   **「選択モーダルの候補集合」と「どのカードがライフに乗ったか／デッキが減らないこと」**。
// 🔑どちらのシナリオも銀行役は `PR-378`（選択する物語／スペル・《無》×0）の選択肢①
//   「あなたのシグニ１体を対象とし、それをバニッシュする。そうした場合、カードを１枚引き、このカードを
//   ゲームから除外する」＝クラス限定が無いのでどのシグニでもバニッシュでき、**バニッシュ先はエナゾーン**。
// ⚠**`Restriction` 列（「ウムル限定」等）は使用 UI を実際にゲートする**＝最初に選んだ `WD08-018` は
//   ウムル限定で CardModal に「発動」ボタンが出ず 34反復空振りした（`Team` 列が "-" でも別列で縛られる）。
// ⚠選択肢②は「デッキの一番上をエナゾーンに置く」＝**エナの中身が変わって候補集合の観測が濁る**ので、
//   必ず①（ドロー枝）を選ぶ。
// ⚠デッキを空にしない（罠22＝解決中リフレッシュで盤面追跡が壊れる）。
const B54_BANISHER = 'PR-378#3801';          // 選択する物語（スペル・無×0・限定なし）
const B54_SELF_FIELD = 'WD14-012#3802';      // 毒蛇の華 アシュタルス（【自】バニッシュ時＝エナから自分を場に）
const B54_SELF_LIFE = 'WXDi-P08-038#3803';   // 大盗罠 ルパンヌ（【自】バニッシュ時＝エナから自分をライフに）
// エナのデコイ＝**旧実装ならこの2枚も候補に出る**（`cardType:'シグニ'` しか見ていなかった）。
const B54_DECOY_A = 'WD01-010#3811';
const B54_DECOY_B = 'WD01-013#3812';
const B54_DECK = ['WD01-012#3821', 'WD01-014#3822', 'WD01-011#3823', 'WD01-010#3824', 'WD01-013#3825',
  'WD01-009#3826', 'WD01-016#3827', 'WD01-012#3828', 'WD01-014#3829', 'WD01-011#3830'];
const B54_LIFE = ['WD01-010#3841', 'WD01-013#3842', 'WD01-012#3843'];

// ⚠`CORE_FIELD_KEYS`（lrig / signi / assist_* / check / key_piece / free_zone / beat_zone）は
//   自分で書き切らないと**前シナリオの盤面が残る**（§4.4 の1）＝両サイド全部を固定する。
function b54Spec(selfCard) {
  return {
    hostSet: {
      'field.lrig': ['WD03-002#3851'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [[selfCard], null, null], 'field.signi_down': [false, false, false],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'energy': [B54_DECOY_A, B54_DECOY_B], 'trash': [], 'actions_done': [],
      'life_cloth': B54_LIFE, 'deck': B54_DECK,
    },
    guestSet: {
      'field.lrig': ['WD01-001#3861'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, null, null], 'field.signi_down': [false, false, false],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [], 'trash': [],
      'deck': ['WD01-013#3871', 'WD01-013#3872', 'WD01-013#3873'],
    },
    handPrepend: [B54_BANISHER],
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}

// スペル `WD08-018` を撃って対象を1体バニッシュするところまで。0コストなので「発動する」がすぐ押せる。
async function b54CastBanisher(page, H, flow, victim) {
  if (!flow.handOpened) { const d = await H.clickTestId('my-hand-card-0'); if (d) { flow.handOpened = true; return d; } }
  if (!flow.cast) {
    const fire = page.getByRole('button', { name: '発動する', exact: true }).first();
    if (await fire.count() && await fire.isVisible().catch(() => false) && await fire.isEnabled().catch(() => false)) {
      await fire.click().catch(() => {}); flow.cast = true; return 'btn:発動する';
    }
    const open = page.getByRole('button', { name: '発動', exact: true }).first();
    if (await open.count() && await open.isVisible().catch(() => false) && await open.isEnabled().catch(() => false)) {
      await open.click().catch(() => {}); return 'btn:発動';
    }
    const e0 = page.getByTestId('spellcost-energy-0').first();
    if (await e0.count() && await e0.isVisible().catch(() => false)) { await e0.click().catch(() => {}); return 'spellcost-energy-0'; }
    return null;
  }
  // 選択肢①（ドロー枝）を選ぶ。②はデッキ上をエナへ置くのでエナの観測が濁る。
  if (!flow.choicePicked) {
    const c = page.getByRole('button', { name: '1枚引き自身を除外', exact: false }).first();
    if (await c.count() && await c.isVisible().catch(() => false) && await c.isEnabled().catch(() => false)) {
      await c.click().catch(() => {}); flow.choicePicked = true; return 'btn:選択肢①(ドロー枝)';
    }
  }
  if (!flow.victimPicked) {
    const d = await clickPendingInstance(page, H, victim);
    if (d) { flow.victimPicked = true; return d; }
  }
  return null;
}

scenarios.b54EnergySelfReviveOnlySelf = {
  title: 'O-54 WD14-012-E1：バニッシュ後の「エナゾーンから場に出す」候補は**自分自身の1枚だけ**（デコイ2枚は出ない）',
  spec: b54Spec(B54_SELF_FIELD),
  async drive(page, H) {
    await H.ensureMain();
    const flow = { handOpened: false, cast: false, choicePicked: false, victimPicked: false };
    let reviveCands = null; let revivePicked = false; let settle = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${SHOT}/b54revive-${s}.png`, fullPage: true }).catch(() => {});
      let did = await b54CastBanisher(page, H, flow, B54_SELF_FIELD);
      const st = await H.queryState();
      // 「機構が動いた証拠」＝**自分自身がエナに居る間に立った候補集合**（罠4＝盤面だけ見ると
      //  機構を通らなくても同じ絵になる）。バニッシュ前の対象選択とはこの条件で弁別する。
      const selfInEnergy = (st?.host?.energyCards ?? []).includes(B54_SELF_FIELD);
      if (!reviveCands && selfInEnergy && Array.isArray(st?.pendingCandidates) && st.pendingCandidates.length > 0) {
        reviveCands = [...st.pendingCandidates];
      }
      if (!did && reviveCands && !revivePicked) {
        const d = await clickPendingInstance(page, H, B54_SELF_FIELD);
        if (d) { revivePicked = true; did = d; }
      }
      if (!did) did = await H.clickZone();
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      H.log(`  b54revive[${s}] -> ${did ?? 'なし'} | cast=${flow.cast} choice=${flow.choicePicked} victim=${flow.victimPicked} cands=${JSON.stringify(reviveCands)} picked=${revivePicked} ena=${JSON.stringify(st?.host?.energyCards)} field=${JSON.stringify(st?.host?.fieldSigni)} pEff=${st?.pendingEffect ?? '-'}`);
      if (!revivePicked) continue;
      settle = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? settle + 1 : 0;
      if (settle < 3) continue;
      // 🔴本命＝候補集合が自分自身1枚だけ（旧実装ならデコイ2枚を足した3枚になる）。
      const onlySelf = !!reviveCands && reviveCands.length === 1 && reviveCands[0] === B54_SELF_FIELD;
      const backOnField = (st.host.fieldSigni ?? []).some(z => (z ?? []).at(-1) === B54_SELF_FIELD);
      const enaCards = st.host.energyCards ?? [];
      const decoysUntouched = enaCards.includes(B54_DECOY_A) && enaCards.includes(B54_DECOY_B) && !enaCards.includes(B54_SELF_FIELD);
      return {
        pass: onlySelf && backOnField && decoysUntouched,
        detail: `候補=${JSON.stringify(reviveCands)}（自分自身1枚だけ=${onlySelf}・旧実装はデコイ2枚を足した3枚）`
          + `／場に復帰=${backOnField}（fieldSigni=${JSON.stringify(st.host.fieldSigni)}）`
          + `／エナ=${JSON.stringify(enaCards)}（デコイ2枚は不動・自分は抜けた=${decoysUntouched}）`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cast=${flow.cast} victim=${flow.victimPicked} cands=${JSON.stringify(reviveCands)} picked=${revivePicked} ena=${JSON.stringify(fin?.host?.energyCards)} field=${JSON.stringify(fin?.host?.fieldSigni)} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};

scenarios.b54EnergySelfToLife = {
  title: 'O-54 WXDi-P08-038-E1：エナの**自分自身**がライフに乗り、デッキはスペルのドロー1枚しか減らない',
  spec: b54Spec(B54_SELF_LIFE),
  async drive(page, H) {
    await H.ensureMain();
    const before = await H.queryState();
    const flow = { handOpened: false, cast: false, choicePicked: false, victimPicked: false };
    let sawSelfInEnergy = false; let settle = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${SHOT}/b54life-${s}.png`, fullPage: true }).catch(() => {});
      let did = await b54CastBanisher(page, H, flow, B54_SELF_LIFE);
      const st = await H.queryState();
      // 機構が動いた証拠＝一度でも「自分自身がエナに居た」こと（＝バニッシュが実際に走った）。
      if ((st?.host?.energyCards ?? []).includes(B54_SELF_LIFE)) sawSelfInEnergy = true;
      // 任意コスト「あなたのライフクロス１枚をトラッシュに置いてもよい」の pay 枝を選ぶ。
      if (!did) did = await H.clickTextOrBtn(['発動する', '支払う']);
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      H.log(`  b54life[${s}] -> ${did ?? 'なし'} | cast=${flow.cast} choice=${flow.choicePicked} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} life=${st?.host?.life} lifeHasSelf=${(st?.host?.lifeCards ?? []).includes(B54_SELF_LIFE)} deck=${st?.host?.deck} ena=${JSON.stringify(st?.host?.energyCards)} pEff=${st?.pendingEffect ?? '-'}`);
      if (!sawSelfInEnergy) continue;
      settle = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? settle + 1 : 0;
      if (settle < 3) continue;
      // 🔴本命＝**ライフに乗るのは自分自身**（旧実装はデッキの一番上が乗り、自分はエナに残った）。
      const selfInLife = (st.host.lifeCards ?? []).includes(B54_SELF_LIFE);
      const enaCards = st.host.energyCards ?? [];
      const leftEnergy = !enaCards.includes(B54_SELF_LIFE);
      const decoysUntouched = enaCards.includes(B54_DECOY_A) && enaCards.includes(B54_DECOY_B);
      // 旧実装の指紋①＝デッキが**もう1枚**減る（スペルのドロー1＋ライフへ1＝-2）。新実装はドロー1だけ。
      const deckMilledOnly = st.host.deck === before.host.deck - 1;
      // 旧実装の指紋②＝任意コストが `lifeTrash` を持たず**ライフを1枚も払わない**ので life が +1 になる。
      //   新実装は「-1（コスト）+1（自分自身）」で差し引き不変。
      const lifeNet = st.host.life === before.host.life;
      return {
        pass: selfInLife && leftEnergy && decoysUntouched && deckMilledOnly && lifeNet,
        detail: `ライフに自分自身=${selfInLife}（lifeCards=${JSON.stringify(st.host.lifeCards)}）`
          + `／エナ=${JSON.stringify(enaCards)}（自分は抜けた=${leftEnergy}・デコイ不動=${decoysUntouched}）`
          + `／deck ${before.host.deck}→${st.host.deck}（スペルのドロー1だけ=${deckMilledOnly}・旧実装は-2）`
          + `／life ${before.host.life}→${st.host.life}（コスト-1と復帰+1で不変=${lifeNet}・旧実装は+1）`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cast=${flow.cast} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} life=${fin?.host?.life} deck=${fin?.host?.deck} ena=${JSON.stringify(fin?.host?.energyCards)} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('b54EnergySelfReviveOnlySelf', 'b54EnergySelfToLife');
// ── O-54 END ──

// ── O-55（2026-08-24）＝【トラップ】設置の**出所**（どこから裏向きに置くか）──────────────
// 🔴`PLACE_TRAP_OPTIONAL` は長らく**手札固定**（`ctx.ownerState.hand` を候補に出す）で、原文が
//   「そのカードを」（＝直前に見たデッキの一番上）や「このシグニをエナゾーンから」と書いていても
//   **手札の別カードを裏向きに置いて**いた（`LOOK_AND_REORDER` の2値フォールバック＝`O-53` と同型）。
// 🔑**gates では守れない層**＝逆翻訳はカード全文 regex で原文を切り出していたので**JSON が出所を
//   持っていなくても緑**だった。実機の観測点は**「候補集合」と「どのゾーンからカードが減ったか」**。
// 🔑銀行役は O-54 と同じ `PR-378`（選択する物語・《無》×0・限定なし）の選択肢①＝
//   「あなたのシグニ１体を対象とし、それをバニッシュする。そうした場合、カードを１枚引き…」。
// ⚠観測対象の2枚はどちらも `Restriction:'あや限定'` だが、**盤面へ直接注入する**ので使用 UI の
//   ゲート（§4.4 の 8k）には掛からない（掛かるのは手札から召喚／使用するときだけ）。
const B55_BANISHER = 'PR-378#3901';          // 選択する物語（スペル・無×0・限定なし）
const B55_ENERGY_SELF = 'WX21-036#3902';     // 中罠 ハトハット（【自】バニッシュ時＝エナの自分自身をトラップに）
const B55_LOOKED = 'WX15-086#3903';          // 小罠 ホイホイ（【自】バニッシュ時＝デッキの一番上をトラップに）
// エナのデコイ＝旧実装との弁別には使わないが「自分だけが抜ける」ことの対照に要る。
const B55_DECOY_A = 'WD01-010#3911';
const B55_DECOY_B = 'WD01-013#3912';
// デッキの並びを固定して「どの札がトラップになったか」を同定する。
// ⚠🔑**銀行役 `PR-378` の選択肢①は先に1枚引く**ので、`WX15-086` の【自】が見る「デッキの一番上」は
//   注入時の先頭ではなく**2枚目**（`B55_DECK_TOP_AFTER_DRAW`）＝これがゲーム的に正しい。
//   1枚目を期待値にすると engine は正しいのに FAIL する（実測で1回踏んだ）。
const B55_DECK_DRAWN = 'WD01-009#3921';              // スペルのドローで手札へ行く1枚目
const B55_DECK_TOP_AFTER_DRAW = 'WD01-012#3922';     // ドロー後の「デッキの一番上」＝トラップになるべき札
const B55_DECK_REST = [B55_DECK_TOP_AFTER_DRAW, 'WD01-014#3923', 'WD01-011#3924', 'WD01-010#3925',
  'WD01-013#3926', 'WD01-016#3927', 'WD01-012#3928', 'WD01-014#3929'];
// 🔑**手札を全部固定する**＝旧実装の指紋は「手札から1枚が消えて裏向きに置かれる」ことなので、
//   手札の中身を1枚ずつ突き合わせられるようにしておく。
const B55_HAND = ['WD01-013#3931', 'WD01-012#3932', 'WD01-011#3933'];

function b55Spec(selfCard) {
  return {
    hostSet: {
      'field.lrig': ['WD03-002#3951'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [[selfCard], null, null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'energy': [B55_DECOY_A, B55_DECOY_B], 'trash': [], 'actions_done': [],
      'life_cloth': ['WD01-010#3941', 'WD01-013#3942', 'WD01-012#3943'],
      'deck': [B55_DECK_DRAWN, ...B55_DECK_REST],
    },
    guestSet: {
      'field.lrig': ['WD01-001#3961'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, null, null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [], 'trash': [],
      'deck': ['WD01-013#3971', 'WD01-013#3972', 'WD01-013#3973'],
    },
    // handPrepend は「先頭に積む」＝`my-hand-card-0` がスペルになる。残りは固定手札。
    handPrepend: [B55_BANISHER, ...B55_HAND],
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}

scenarios.b55TrapFromEnergySelf = {
  title: 'O-55 WX21-036-E1：バニッシュ後の【トラップ】はエナの**自分自身**（手札は1枚も減らない）',
  spec: b55Spec(B55_ENERGY_SELF),
  async drive(page, H) {
    await H.ensureMain();
    const before = await H.queryState();
    const flow = { handOpened: false, cast: false, choicePicked: false, victimPicked: false };
    let sawSelfInEnergy = false; let settle = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${SHOT}/b55ena-${s}.png`, fullPage: true }).catch(() => {});
      let did = await b54CastBanisher(page, H, flow, B55_ENERGY_SELF);
      const st = await H.queryState();
      // 機構が動いた証拠＝一度でも「自分自身がエナに居た」こと（＝バニッシュが実際に走った）。
      if ((st?.host?.energyCards ?? []).includes(B55_ENERGY_SELF)) sawSelfInEnergy = true;
      // 「設置しますか？」→「ゾーンN に設置」の2段。どちらも CHOOSE。
      // ⚠**`clickTextOrBtn` は使わない**（§4.4）＝盤面ログ「ハトハットを【トラップ】として設置しますか？」の
      //   **テキスト**に当たって「押せた」と報告しながら何も進まず、34反復まるごと空振りする（実測）。
      //   ボタン限定の `clickBtn` を使い、**先に進む側（ゾーン選択）から**試す。
      if (!did) did = await H.clickBtn('ゾーン1に設置');
      if (!did) did = await H.clickBtn('【トラップ】として設置する');
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      H.log(`  b55ena[${s}] -> ${did ?? 'なし'} | cast=${flow.cast} choice=${flow.choicePicked} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} traps=${JSON.stringify(st?.host?.signiTraps)} ena=${JSON.stringify(st?.host?.energyCards)} hand=${st?.host?.hand} pEff=${st?.pendingEffect ?? '-'}`);
      if (!sawSelfInEnergy) continue;
      settle = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? settle + 1 : 0;
      if (settle < 3) continue;
      const traps = (st.host.signiTraps ?? []).filter(Boolean);
      // 🔴本命＝裏向きに置かれたのが**自分自身**（旧実装は手札のカードが置かれた）。
      const trapIsSelf = traps.length === 1 && traps[0] === B55_ENERGY_SELF;
      const enaCards = st.host.energyCards ?? [];
      const leftEnergy = !enaCards.includes(B55_ENERGY_SELF);
      const decoysUntouched = enaCards.includes(B55_DECOY_A) && enaCards.includes(B55_DECOY_B);
      // 🔴旧実装の指紋＝**手札から1枚消える**。減ってよいのは使ったスペル（除外）と引いた1枚の差引だけ＝
      //   固定手札 3枚が**全部そのまま残っている**ことを1枚ずつ見る。
      const handCards = st.host.handCards ?? [];
      const handKept = B55_HAND.every(c => handCards.includes(c));
      const noHandInTrap = !B55_HAND.some(c => traps.includes(c));
      return {
        pass: trapIsSelf && leftEnergy && decoysUntouched && handKept && noHandInTrap,
        detail: `traps=${JSON.stringify(st.host.signiTraps)}（自分自身だけ=${trapIsSelf}・旧実装は手札の札が置かれた）`
          + `／エナ=${JSON.stringify(enaCards)}（自分は抜けた=${leftEnergy}・デコイ不動=${decoysUntouched}）`
          + `／固定手札3枚が全部残る=${handKept}・トラップに手札が混ざらない=${noHandInTrap}（hand ${before.host.hand}→${st.host.hand}）`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cast=${flow.cast} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} traps=${JSON.stringify(fin?.host?.signiTraps)} ena=${JSON.stringify(fin?.host?.energyCards)} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};

scenarios.b55TrapFromDeckTop = {
  title: 'O-55 WX15-086-E1：【トラップ】候補は**直前に見たデッキの一番上の1枚だけ**（手札は候補に出ない）',
  spec: b55Spec(B55_LOOKED),
  async drive(page, H) {
    await H.ensureMain();
    const before = await H.queryState();
    const flow = { handOpened: false, cast: false, choicePicked: false, victimPicked: false };
    let trapCands = null; let sawBanish = false; let settle = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${SHOT}/b55look-${s}.png`, fullPage: true }).catch(() => {});
      let did = await b54CastBanisher(page, H, flow, B55_LOOKED);
      const st = await H.queryState();
      if ((st?.host?.energyCards ?? []).includes(B55_LOOKED)) sawBanish = true;
      // 「候補集合そのものを観測する」＝バニッシュ後に立った SELECT_TARGET の候補が本命の観測点。
      if (!trapCands && sawBanish && Array.isArray(st?.pendingCandidates) && st.pendingCandidates.length > 0) {
        trapCands = [...st.pendingCandidates];
      }
      // ⚠ボタン限定（`clickTextOrBtn` は盤面ログのテキストに当たって空振りする）。
      if (!did) did = await H.clickBtn('ゾーン1に設置');
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      H.log(`  b55look[${s}] -> ${did ?? 'なし'} | cast=${flow.cast} victim=${flow.victimPicked} sawBanish=${sawBanish} cands=${JSON.stringify(trapCands)} traps=${JSON.stringify(st?.host?.signiTraps)} deck=${st?.host?.deck} hand=${st?.host?.hand} pEff=${st?.pendingEffect ?? '-'}`);
      if (!sawBanish) continue;
      settle = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? settle + 1 : 0;
      if (settle < 3) continue;
      const traps = (st.host.signiTraps ?? []).filter(Boolean);
      // 🔴本命＝候補集合がデッキの一番上1枚だけ（旧実装は手札4枚が候補に出た）。
      const onlyDeckTop = !!trapCands && trapCands.length === 1 && trapCands[0] === B55_DECK_TOP_AFTER_DRAW;
      const trapIsDeckTop = traps.length === 1 && traps[0] === B55_DECK_TOP_AFTER_DRAW;
      // 複製していないこと＝デッキにもトラップにも同時に居ない。
      const notInDeck = !(st.host.deckCards ?? []).includes(B55_DECK_TOP_AFTER_DRAW);
      const handCards = st.host.handCards ?? [];
      const handKept = B55_HAND.every(c => handCards.includes(c));
      return {
        pass: onlyDeckTop && trapIsDeckTop && notInDeck && handKept,
        detail: `候補=${JSON.stringify(trapCands)}（デッキの一番上1枚だけ=${onlyDeckTop}・旧実装は手札が候補だった）`
          + `／traps=${JSON.stringify(st.host.signiTraps)}（デッキの一番上=${trapIsDeckTop}）`
          + `／デッキに残っていない=${notInDeck}（複製なし・deck ${before.host.deck}→${st.host.deck}）`
          + `／固定手札3枚が全部残る=${handKept}`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cast=${flow.cast} victim=${flow.victimPicked} sawBanish=${sawBanish} cands=${JSON.stringify(trapCands)} traps=${JSON.stringify(fin?.host?.signiTraps)} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('b55TrapFromEnergySelf', 'b55TrapFromDeckTop');
// ── O-55 END ──

// ── O-57（2026-08-24）＝「デッキの一番上を公開する。それが〜の場合、…」が**2文目以降**だと条件ごと落ちる ──
// 🔴既存の `REVEAL_AND_PICK` 規則が `sentences[0]` 固定だったため、公開文の前に宣言や任意コストがある形は
//   「公開」だけが `LOOK_AND_REORDER` に、「場に出す」だけが**素の `ADD_TO_FIELD`（filter 無し）**に割れ、
//   **「それが〈条件〉の場合」が JSON のどこにも残らない＝デッキトップが何でも場に出る過剰実行**だった。
// 🔑**gates では守れない層**＝逆翻訳は分裂した2アクションをそれぞれ日本語にできるので**逆翻訳シートは緑**。
//   実機の観測点は**「候補が出るか出ないか」と「デッキトップが場に出たか／デッキに残ったか」**。
// 🔑観測対象は `WXDi-P02-044-E1`＝この1枚で **任意コスト → 公開 → 候補フィルタ → ダウン配置** を全部通る：
//   「【自】：このシグニがバニッシュされたとき、このシグニをエナゾーンからデッキの一番下に置いてもよい。
//     そうした場合、あなたのデッキの一番上を公開する。そのカードが**レベル３**のシグニの場合、
//     そのシグニを**ダウン状態で**場に出しても**よい**。」
// 🔑**対照は「デッキの一番上だけ」を差し替える**（§4.4 の3）＝盤面・手順は1文字も変えない。
//   ・本命＝トップが**レベル3**（`WD01-010` 大剣 カリバン）→ 場に出て**ダウン状態**・デッキから消える
//   ・対照＝トップが**レベル2**（`WD01-012` 中剣 フランベル）→ **1体も場に出ず、トップはデッキに残る**
//     （旧実装なら filter が無いのでレベル2でも場に出た＝これが決定的な指紋）
// 🔑銀行役は O-54／O-55 と同じ `PR-378`（選択する物語・《無》×0・限定なし）の選択肢①。
// ⚠`PR-378` の①は**先に1枚引く**ので、【自】が見る「デッキの一番上」は注入時の先頭ではなく**2枚目**（§4.4 8z）。
const B57_BANISHER = 'PR-378#4001';
const B57_SELF = 'WXDi-P02-044#4002';        // 羅植姫 ゴーシュ・アグネーゼ（Lv3・限定なし）
const B57_DRAWN = 'WD01-014#4011';           // スペルのドローで手札へ行く1枚目
const B57_TOP_L3 = 'WD01-010#4012';          // ドロー後のトップ＝レベル3（本命で場に出るべき札）
const B57_TOP_L2 = 'WD01-012#4013';          // 同・レベル2（対照で場に出てはいけない札）
const B57_DECK_REST = ['WD01-011#4021', 'WD01-013#4022', 'WD01-016#4023', 'WD01-009#4024',
  'WD01-017#4025', 'WD01-010#4026', 'WD01-012#4027'];
// 手札を固定して「手札から出していない」ことも見る（旧実装の bare ADD_TO_FIELD はデッキトップだが、
// 念のため手札が動かないことを対照に入れる）。
const B57_HAND = ['WD01-013#4031', 'WD01-012#4032', 'WD01-011#4033'];

// ⚠`CORE_FIELD_KEYS` は自分で書き切らないと前シナリオの盤面が残る（§4.4 の1）＝両サイド全部を固定する。
function b57Spec(topCard) {
  return {
    hostSet: {
      'field.lrig': ['WD03-002#4051'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [[B57_SELF], null, null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'energy': [], 'trash': [], 'actions_done': [],
      'life_cloth': ['WD01-010#4041', 'WD01-013#4042', 'WD01-012#4043'],
      // 1枚目＝スペルのドローで抜ける／2枚目＝【自】が公開する「デッキの一番上」
      'deck': [B57_DRAWN, topCard, ...B57_DECK_REST],
    },
    guestSet: {
      'field.lrig': ['WD01-001#4061'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, null, null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [], 'trash': [],
      'deck': ['WD01-013#4071', 'WD01-013#4072', 'WD01-013#4073'],
    },
    handPrepend: [B57_BANISHER, ...B57_HAND],
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}

scenarios.b57RevealTopLevelMatch = {
  title: 'O-57 WXDi-P02-044-E1：公開したトップが**レベル3**なら**ダウン状態で**場に出る（デッキから消える）',
  spec: b57Spec(B57_TOP_L3),
  async drive(page, H) {
    await H.ensureMain();
    const before = await H.queryState();
    const flow = { handOpened: false, cast: false, choicePicked: false, victimPicked: false };
    let sawSelfInEnergy = false; let settle = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${SHOT}/b57hit-${s}.png`, fullPage: true }).catch(() => {});
      let did = await b54CastBanisher(page, H, flow, B57_SELF);
      const st = await H.queryState();
      // 機構が動いた証拠＝一度でも「自分自身がエナに居た」こと（＝バニッシュが実際に走った）。
      if ((st?.host?.energyCards ?? []).includes(B57_SELF)) sawSelfInEnergy = true;
      // 任意コスト（エナの自分自身をデッキの一番下へ）の pay 枝 → 公開札のピック → ゾーン選択。
      // ⚠ボタン限定（`clickTextOrBtn` は盤面ログのテキストに当たって空振りする＝§4.4 2b）。
      if (!did) did = await H.clickBtn('発動する');
      if (!did) did = await H.clickZone();
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      H.log(`  b57hit[${s}] -> ${did ?? 'なし'} | cast=${flow.cast} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} field=${JSON.stringify(st?.host?.fieldSigni)} down=${JSON.stringify(st?.host?.signiDown)} deck=${st?.host?.deck} pEff=${st?.pendingEffect ?? '-'}`);
      if (!sawSelfInEnergy) continue;
      settle = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? settle + 1 : 0;
      if (settle < 3) continue;
      const zone = (st.host.fieldSigni ?? []).findIndex(z => (z ?? []).at(-1) === B57_TOP_L3);
      // 🔴本命＝レベル3のトップが場に出て、**ダウン状態**で、**デッキから消えている**（複製なし）。
      const onField = zone >= 0;
      const isDown = onField && (st.host.signiDown ?? [])[zone] === true;
      const goneFromDeck = !(st.host.deckCards ?? []).includes(B57_TOP_L3);
      // 任意コスト（エナの自分自身をデッキの一番下へ）が実際に払われたこと。
      const selfToDeck = (st.host.deckCards ?? []).includes(B57_SELF) && !(st.host.energyCards ?? []).includes(B57_SELF);
      const handKept = B57_HAND.every(c => (st.host.handCards ?? []).includes(c));
      return {
        pass: onField && isDown && goneFromDeck && selfToDeck && handKept,
        detail: `レベル3トップが場に=${onField}（zone${zone + 1}・fieldSigni=${JSON.stringify(st.host.fieldSigni)}）／ダウン状態=${isDown}（signiDown=${JSON.stringify(st.host.signiDown)}）`
          + `／デッキから消えた=${goneFromDeck}（複製なし）／任意コスト（自分自身がエナ→デッキ）を実際に払った=${selfToDeck}`
          + `／固定手札3枚が残る=${handKept}（deck ${before.host.deck}→${st.host.deck}）`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cast=${flow.cast} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} field=${JSON.stringify(fin?.host?.fieldSigni)} deck=${fin?.host?.deck} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};

scenarios.b57RevealTopLevelMiss = {
  title: 'O-57 対照 WXDi-P02-044-E1：トップが**レベル2**なら1体も場に出ず、そのままデッキに残る',
  spec: b57Spec(B57_TOP_L2),
  async drive(page, H) {
    await H.ensureMain();
    const before = await H.queryState();
    const flow = { handOpened: false, cast: false, choicePicked: false, victimPicked: false };
    let sawSelfInEnergy = false; let settle = 0;
    for (let s = 0; s < 34; s++) {
      await page.waitForTimeout(600);
      await page.screenshot({ path: `${SHOT}/b57miss-${s}.png`, fullPage: true }).catch(() => {});
      let did = await b54CastBanisher(page, H, flow, B57_SELF);
      const st = await H.queryState();
      if ((st?.host?.energyCards ?? []).includes(B57_SELF)) sawSelfInEnergy = true;
      if (!did) did = await H.clickBtn('発動する');
      if (!did) did = await H.clickZone();
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      H.log(`  b57miss[${s}] -> ${did ?? 'なし'} | cast=${flow.cast} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} field=${JSON.stringify(st?.host?.fieldSigni)} deck=${st?.host?.deck} pEff=${st?.pendingEffect ?? '-'}`);
      // 「クリック前から成立している条件で判定しない」（§4.4 の5）＝バニッシュが走ったことを見てから数える。
      if (!sawSelfInEnergy) continue;
      settle = (!st?.pendingEffect && (st?.stackLen ?? 0) === 0) ? settle + 1 : 0;
      if (settle < 4) continue;
      // 🔴本命＝レベル2のトップは**場に出ず**、**デッキに残る**（旧実装は filter が無いので出た）。
      const notOnField = !(st.host.fieldSigni ?? []).some(z => (z ?? []).at(-1) === B57_TOP_L2);
      const stillInDeck = (st.host.deckCards ?? []).includes(B57_TOP_L2);
      const emptyField = (st.host.fieldSigni ?? []).every(z => (z ?? []).length === 0);
      // 機構自体は動いた証拠＝任意コストは払われている（＝「何も起きなかった」ではない）。
      const selfToDeck = (st.host.deckCards ?? []).includes(B57_SELF) && !(st.host.energyCards ?? []).includes(B57_SELF);
      const handKept = B57_HAND.every(c => (st.host.handCards ?? []).includes(c));
      return {
        pass: notOnField && stillInDeck && emptyField && selfToDeck && handKept,
        detail: `レベル2トップは場に出ない=${notOnField}／デッキに残る=${stillInDeck}／場は空のまま=${emptyField}（fieldSigni=${JSON.stringify(st.host.fieldSigni)}）`
          + `／任意コストは払われた=${selfToDeck}（＝機構は通っている・「何も起きなかった」ではない）`
          + `／固定手札3枚が残る=${handKept}（deck ${before.host.deck}→${st.host.deck}）`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（cast=${flow.cast} victim=${flow.victimPicked} sawEna=${sawSelfInEnergy} field=${JSON.stringify(fin?.host?.fieldSigni)} deck=${fin?.host?.deck} pEff=${fin?.pendingEffect ?? '-'}）` };
  },
};
order.push('b57RevealTopLevelMatch', 'b57RevealTopLevelMiss');
// ── O-57 END ──

// ── O-56（2026-08-24）＝TRAP_OP / TRAP_OPERATION の文単位ペイロード ──────────────
// 旧executorは EffectText+BurstText の全文 includes で枝を決めたため、WX17-044-E1 は後段の
// 「トラッシュに置く／トラップアイコンを発動」に食われ、設置が起きなかった。
// 修正後は E1 の trapOp:set だけを読み、既存の INTERNAL_ASK_TRAP_ZONE → INTERNAL_PICK_TO_TRAP へ進む。
const O56_ARROW = 'WX17-044#5601';
const O56_OLD_TRAP = 'WD01-013#5602';
const O56_PICK = 'WD01-014#5611';
const O56_LOOKED = [O56_PICK, 'WD01-012#5612', 'WD01-013#5613', 'WD03-010#5614', 'WD03-011#5615'];
const O56_DECK_REST = ['WD01-009#5616', 'WD01-010#5617', 'WD01-011#5618'];
const O56_BLUE_A = 'WD03-010#5621';
const O56_BLUE_B = 'WD03-011#5622';

function o56ArrowSpec() {
  return {
    hostSet: {
      'field.lrig': ['WX15-002#5651'], // Lv4あや＝限定とスペル条件を満たす
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, null, null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, O56_OLD_TRAP],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [O56_BLUE_A, O56_BLUE_B], 'trash': [], 'actions_done': [],
      'life_cloth': ['WD01-010#5631', 'WD01-013#5632', 'WD01-012#5633'],
      'deck': [...O56_LOOKED, ...O56_DECK_REST],
    },
    guestSet: {
      'field.lrig': ['WD01-001#5652'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, null, null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null],
      'field.check': null, 'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [], 'trash': [],
      'deck': ['WD01-013#5641', 'WD01-013#5642', 'WD01-013#5643'],
    },
    handPrepend: [O56_ARROW],
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  };
}

async function driveO56Arrow(page, H, id, check) {
  await H.ensureMain();
  const before = await H.queryState();
  const flow = { handOpened: false, energy0: false, energy1: false, cast: false, picked: false };
  let settle = 0;
  for (let s = 0; s < 42; s++) {
    await page.waitForTimeout(600);
    await page.screenshot({ path: `${SHOT}/${id}-${s}.png`, fullPage: true }).catch(() => {});
    let did = null;
    if (!flow.handOpened) {
      did = await H.clickTestId('my-hand-card-0');
      if (did) flow.handOpened = true;
    }
    if (!did && !flow.cast) {
      const e0 = page.getByTestId('spellcost-energy-0').first();
      const e1 = page.getByTestId('spellcost-energy-1').first();
      if (!flow.energy0 && await e0.count() && await e0.isVisible().catch(() => false)) {
        await e0.click().catch(() => {}); flow.energy0 = true; did = 'spellcost-energy-0';
      } else if (!flow.energy1 && await e1.count() && await e1.isVisible().catch(() => false)) {
        await e1.click().catch(() => {}); flow.energy1 = true; did = 'spellcost-energy-1';
      } else if (flow.energy0 && flow.energy1) {
        const fire = page.getByRole('button', { name: '発動する', exact: true }).first();
        if (await fire.count() && await fire.isVisible().catch(() => false) && await fire.isEnabled().catch(() => false)) {
          await fire.click().catch(() => {}); flow.cast = true; did = 'btn:発動する';
        }
      }
      if (!did) did = await H.clickBtn('発動');
    }
    const mid = await H.queryState();
    if (!did && flow.cast && !flow.picked && (mid?.pendingCandidates ?? []).includes(O56_PICK)) {
      did = await clickPendingInstance(page, H, O56_PICK);
      if (did) flow.picked = true;
    }
    // 🔴**ゾーン選択を `flow.picked` でゲートしない**（続き646 の実機で踏んだ）＝
    //   「好きな枚数」の選択は `pendingCandidates` を持つ SELECT_TARGET ではなく **SEARCH**（デッキ上5枚公開）で行われ、
    //   実際のピックは下の `stdStep` の `pick-0` / `決定 (1/5)` が処理する。よって `clickPendingInstance` は一度も走らず
    //   `flow.picked` は永久に false のままで、**ゾーン選択の CHOOSE が出ているのに誰も押さずに42反復空振り**した。
    //   ⚠engine は正しく `SEARCH → 決定 (1/5) → INTERNAL_ASK_TRAP_ZONE` と進んでいる（枚数は SEARCH 側で選ぶので
    //     ゾーン選択にスキップが無いのが正しい）。⇒ **cast 済みなら無条件にゾーン1を試す。**
    //   ⚠ゾーン1は空（既存【トラップ】はゾーン3）＝`o56ArrowRainSetsTrapNotTrashesIt` の「既存を捨てない」assert を壊さない。
    if (!did && flow.cast) {
      did = await H.clickBtn('ゾーン1に設置');
      if (did) flow.picked = true;
    }
    if (!did) did = await H.stdStep(['決定 (1/5)', '決定', '発動順序を確定', '確定', 'OK', 'はい']);
    const st = await H.queryState();
    H.log(`  ${id}[${s}] -> ${did ?? 'なし'} | flow=${JSON.stringify(flow)} cands=${JSON.stringify(st?.pendingCandidates)} traps=${JSON.stringify(st?.host?.signiTraps)} deck=${JSON.stringify(st?.host?.deckCards)} trash=${JSON.stringify(st?.host?.trashCards)} pEff=${st?.pendingEffect ?? '-'} stack=${st?.stackLen ?? '-'}`);
    const installed = (st?.host?.signiTraps ?? []).includes(O56_PICK);
    settle = installed && !st?.pendingEffect && (st?.stackLen ?? 0) === 0 ? settle + 1 : 0;
    if (settle >= 3) return check(st, before);
  }
  const fin = await H.queryState();
  return { pass: false, detail: `未完了（flow=${JSON.stringify(flow)} traps=${JSON.stringify(fin?.host?.signiTraps)} deck=${JSON.stringify(fin?.host?.deckCards)} pEff=${fin?.pendingEffect ?? '-'}）` };
}

scenarios.o56TrapSetFromDeckNoDuplicate = {
  title: 'O-56 デッキ由来のトラップ設置は元デッキから抜け、同じinstanceを複製しない',
  spec: o56ArrowSpec(),
  drive: (page, H) => driveO56Arrow(page, H, 'o56nodup', (st) => {
    const inTrap = (st.host.signiTraps ?? []).includes(O56_PICK);
    const outOfDeck = !(st.host.deckCards ?? []).includes(O56_PICK);
    return {
      pass: inTrap && outOfDeck,
      detail: `設置=${inTrap}／デッキから除去=${outOfDeck}（traps=${JSON.stringify(st.host.signiTraps)} deck=${JSON.stringify(st.host.deckCards)}）`,
    };
  }),
};

scenarios.o56ArrowRainSetsTrapNotTrashesIt = {
  title: 'O-56 WX17-044-E1は設置を行い、別文の「トラッシュ／発動」で既存トラップを捨てない',
  spec: o56ArrowSpec(),
  drive: (page, H) => driveO56Arrow(page, H, 'o56arrow', (st) => {
    const installed = (st.host.signiTraps ?? []).includes(O56_PICK);
    const oldKept = (st.host.signiTraps ?? []).includes(O56_OLD_TRAP);
    const oldNotTrashed = !(st.host.trashCards ?? []).includes(O56_OLD_TRAP);
    return {
      pass: installed && oldKept && oldNotTrashed,
      detail: `新規設置=${installed}／既存トラップ残存=${oldKept}／既存トラップ非トラッシュ=${oldNotTrashed}`,
    };
  }),
};

// WXK11-036-E2：「チェックゾーンにあるかのように」はLBを実行するだけで field.check を変えない。
// デッキの上・下どちらを既存TRASHが選んでも同じ観測になるよう、両端を「LB:1枚引く」のLv3シグニにする。
const O56_DEMENI = 'WXK11-036#5661';
const O56_DEFENDER = 'WD01-014#5662';
const O56_BURST_TOP = 'WD03-011#5663';
const O56_BURST_BOTTOM = 'WD01-011#5664';

scenarios.o56BurstAsCheckDoesNotEnterCheckZone = {
  title: 'O-56 WXK11-036-E2はLBをチェックゾーン扱いで発動するがfield.checkへ実際には置かない',
  spec: {
    hostSet: {
      'field.lrig': ['WX15-012#5671'], // Lv3＝両LBシグニのレベル条件を満たす
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, [O56_DEMENI], null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null], 'field.check': null,
      'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [], 'trash': [], 'actions_done': [], 'life_cloth': [],
      // ⚠**デッキを2枚にしない**（続き646 の実機で踏んだ）＝LB の「1枚引く」でデッキが尽きると
      //   **リフレッシュが走ってトラッシュのカードがデッキへ戻り**、`LB元はトラッシュ` の assert が
      //   engine は正しいのに false になる。間に捨て札を挟んで**引いても尽きない厚み**を持たせる。
      //   ⚠添字0が「デッキの一番下」＝ミルされるのは `O56_BURST_TOP`（名前と位置が逆だが既存の並びを維持）。
      'deck': [O56_BURST_TOP, 'WD01-013#5665', 'WD01-013#5666', 'WD01-013#5667', 'WD01-013#5668', O56_BURST_BOTTOM],
    },
    guestSet: {
      'field.lrig': ['WD01-001#5672'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, [O56_DEFENDER], null], 'field.signi_down': [false, false, false],
      'field.signi_traps': [null, null, null], 'field.check': null,
      'field.key_piece': null, 'field.free_zone': [], 'field.beat_zone': [],
      'lrig_deck': [], 'hand': [], 'energy': [], 'trash': [], 'life_cloth': [],
      'deck': ['WD01-013#5673', 'WD01-013#5674'],
    },
    top: { active: 'host', turn_phase: 'ATTACK_SIGNI', turn_count: 2 },
  },
  async drive(page, H) {
    const before = await H.queryState();
    const attack = { zoneOpened: false, attacked: false };
    let settle = 0;
    for (let s = 0; s < 32; s++) {
      await page.waitForTimeout(650);
      await page.screenshot({ path: `${SHOT}/o56burst-${s}.png`, fullPage: true }).catch(() => {});
      let did = await v86Attack(page, H, attack, 1);
      if (!did) did = await H.clickBtn('発動する');
      if (!did) did = await H.stdStep(['発動順序を確定', '確定', '決定', 'OK', 'ガードしない']);
      const st = await H.queryState();
      H.log(`  o56burst[${s}] -> ${did ?? 'なし'} | attacked=${attack.attacked} hand=${st?.host?.hand} check=${st?.host?.fieldCheck ?? '-'} trash=${JSON.stringify(st?.host?.trashCards)} pEff=${st?.pendingEffect ?? '-'} stack=${st?.stackLen ?? '-'}`);
      settle = attack.attacked && !st?.pendingEffect && (st?.stackLen ?? 0) === 0 ? settle + 1 : 0;
      if (settle < 4) continue;
      const burstRan = (st.host.hand ?? 0) === (before.host.hand ?? 0) + 1;
      const checkUnchanged = st.host.fieldCheck === null;
      const sourceTrashed = (st.host.trashCards ?? []).includes(O56_BURST_TOP)
        || (st.host.trashCards ?? []).includes(O56_BURST_BOTTOM);
      return {
        pass: burstRan && checkUnchanged && sourceTrashed,
        detail: `LBで1枚ドロー=${burstRan}／field.check不変(null)=${checkUnchanged}／LB元はトラッシュ=${sourceTrashed}`,
      };
    }
    const fin = await H.queryState();
    return { pass: false, detail: `未完了（attacked=${attack.attacked} hand=${fin?.host?.hand} check=${fin?.host?.fieldCheck ?? '-'} trash=${JSON.stringify(fin?.host?.trashCards)}）` };
  },
};

order.push('o56TrapSetFromDeckNoDuplicate', 'o56ArrowRainSetsTrapNotTrashesIt',
  'o56BurstAsCheckDoesNotEnterCheckZone');
// ── O-56 END ──

// ── §5.2 段2 第41バッチ START ──
// `turn_phase:'END'` の直接注入は room 正規化に負けるため、V-30 と同じくフェイズボタンを実際に歩く。
const B41_DURATION_SIGNI = 'WX05-057#54101';
const B41_OWNER_SOURCE = 'WX25-P3-059#54111';
const B41_OWNER_SELF = 'WD01-013#54112';
const B41_OWNER_OPP = 'WD01-012#54113';

scenarios.b41GrantKeywordExpiresAtTurnEnd = {
  title: '段2 第41バッチ：WD15-002-E1へグロウすると【ダブルクラッシュ】が実UI経由で実際に乗る（期間の固定は golden 側）',
  spec: {
    hostSet: {
      'field.lrig': ['WX14-010#54100'],
      'field.assist_lrig_l': [], 'field.assist_lrig_r': [],
      'field.signi': [null, [B41_DURATION_SIGNI], null],
      'field.signi_down': [false, false, false],
      'lrig_deck': ['WD15-002#54102'],
      'energy': ['WX04-072#54103', 'WX04-072#54104'],
      'hand': [], 'trash': [], 'actions_done': [],
      'deck': ['WD01-013#54105', 'WD01-013#54106', 'WD01-013#54107'],
    },
    guestSet: {
      'field.lrig': ['WD01-001#54108'],
      'field.signi': [null, null, null],
      'deck': ['WD01-013#54109', 'WD01-013#54110'],
    },
    top: { active: 'host', turn_phase: 'GROW', turn_count: 2 },
  },
  async drive(page, H) {
    const opened = await H.openGrow(/紅乙女.*遊月・参/);
    if (!opened) return { pass: false, detail: 'WD15-002のグロウ候補を開けず' };
    let selected = 0; let applied = false; let settled = null;
    for (let s = 0; s < 30; s++) {
      await page.waitForTimeout(500);
      let did = null;
      const growExec = page.getByRole('button', { name: 'グロウ実行', exact: true }).first();
      if (await growExec.count() && await growExec.isVisible().catch(() => false)) {
        if (!(await growExec.isEnabled().catch(() => false)) && selected < 2) {
          // 🔴**`.first()` を2回押さない**（続き647 の実機で踏んだ）＝同じエナをトグルして
          //   選択が解除され、`selected` は2でも実際は0枚のまま「グロウ実行」が永久に disabled になる
          //   （lrig が最後まで変わらず30反復空振りした）。⇒ **`.nth(selected)` で別のカードを押す。**
          const energy = page.getByText('エナから選択').locator('..').locator('div[style*="cursor: pointer"]').nth(selected);
          if (await energy.count() && await energy.isVisible().catch(() => false)) {
            await energy.click().catch(() => {}); selected++; did = `grow-energy-${selected}`;
          }
        } else if (await growExec.isEnabled().catch(() => false)) {
          await growExec.click().catch(() => {}); did = 'btn:グロウ実行';
        }
      }
      if (!did) did = await H.clickTextOrBtn(['発動順序を確定', '確定', '決定', 'OK', 'はい']);
      const st = await H.queryState();
      applied ||= (st?.host?.keywordGrants ?? []).some(g => g.startsWith(`${B41_DURATION_SIGNI}:`) && g.includes('ダブルクラッシュ'));
      H.log(`  b41duration[${s}] -> ${did ?? 'なし'} | selected=${selected} lrig=${st?.host?.lrigTop} applied=${applied} grants=${JSON.stringify(st?.host?.keywordGrants)} pEff=${st?.pendingEffect ?? '-'} stack=${st?.stackLen ?? '-'}`);
      if (applied && !st?.pendingEffect && (st?.stackLen ?? 0) === 0) { settled = st; break; }
    }
    if (!settled) return { pass: false, detail: `付与直後を確認できず（selected=${selected} applied=${applied}）` };
    // 🔴**「ターンをまたぐと消える」は実機では検査できない**（続き647 の実測で確定・元実装から削除した）＝
    //   現 engine は `keyword_grants` を**duration に関係なくターン末に一括クリア**するため、
    //   修正前の `PERMANENT` でも同じく消える＝**この assert は判別力ゼロ**（常に緑になる偽の対照）。
    //   ⚠元実装は代替として `fetch('/data/effects_misc.json')` で `action.duration` を読んでいたが、
    //     それは**挙動ではなくデータを見ているだけ**＝golden と同じことをブラウザ経由でやる形なので外した。
    //     期間の固定は golden 側（段2 第41バッチの duration テスト群）が担当する。
    //   ⇒ **実機がここで守れるのは「付与が実 UI 経由で実際に乗る」ことだけ**。それに絞る。
    const granted = (settled.host.keywordGrants ?? []).filter(g => g.startsWith(`${B41_DURATION_SIGNI}:`));
    return {
      pass: applied && granted.some(g => g.includes('ダブルクラッシュ')),
      detail: `グロウ経由で【ダブルクラッシュ】が実際に乗った=${applied}／付与内容=${JSON.stringify(granted)}`,
    };
  },
};

scenarios.b41GrantKeywordTargetsOwnSigniOnly = {
  title: '§5.3 O-61：WX25-P3-059-E1「あなたのシグニ１体を対象とし」で対象ピッカーが出て、選んだ側だけに乗る',
  spec: {
    hostSet: {
      'field.lrig': ['WD03-003#54120'],
      'field.signi': [[B41_OWNER_SOURCE], [B41_OWNER_SELF], null],
      'field.signi_down': [false, false, false],
      'field.check': null,
      'energy': ['WD03-013#54114'],
      'hand': [], 'trash': [], 'actions_done': [],
      'deck': ['WD01-013#54115', 'WD01-013#54116'],
    },
    guestSet: {
      'field.lrig': ['WD01-001#54121'],
      'field.signi': [[B41_OWNER_OPP], null, null],
      'field.check': null,
      'deck': ['WD01-013#54117', 'WD01-013#54118'],
    },
    top: { active: 'host', turn_phase: 'MAIN', turn_count: 2 },
  },
  async drive(page, H) {
    // 🔑**O-61 の本体**＝原文は「あなたのシグニ１体を**対象とし**、《青》を支払ってもよい」。
    //   旧 engine は `GRANT_KEYWORD` の「target.filter が無い＝このシグニ」という緩い既定に飲まれ、
    //   **`SELECT_TARGET` を一度も出さずに効果元（`B41_OWNER_SOURCE`）へ自動付与**していた（続き647 の実機観測）。
    //   ⇒ ここで見るのは①**ピッカーが出ること**（機構が動いた証拠＝§4.4 罠4）
    //     ②候補が**自分のシグニ2体**で相手シグニを含まないこと
    //     ③**効果元ではない方**（`B41_OWNER_SELF`）を選ぶと**そちらにだけ**乗ること（＝§4.3 の「候補の先頭以外を狙う」）。
    let energyPicked = false; let paid = false; let sawPicker = false; let picked = false;
    let candSnapshot = null;
    for (let s = 0; s < 30; s++) {
      await page.waitForTimeout(500);
      let did = null;
      const st0 = await H.queryState();
      const cands = Array.isArray(st0?.pendingCandidates) ? st0.pendingCandidates : [];
      if (paid && !picked && cands.length > 0) {
        sawPicker = true; candSnapshot = cands;
        const onlyOwn = cands.includes(B41_OWNER_SOURCE) && cands.includes(B41_OWNER_SELF)
          && !cands.includes(B41_OWNER_OPP);
        if (!onlyOwn) {
          return { pass: false, detail: `候補が自分のシグニ2体になっていない＝${JSON.stringify(cands)}` };
        }
        // ⚠**効果元ではない方**を選ぶ（効果元を選ぶと旧実装の自動付与と同じ絵になり判別力が消える）
        did = await clickPendingInstance(page, H, B41_OWNER_SELF);
        if (did) picked = true;
      }
      if (picked) {
        const grants = st0?.host?.keywordGrants ?? [];
        const oppGrants = st0?.guest?.keywordGrants ?? [];
        const onPicked = grants.some(g => g.startsWith(`${B41_OWNER_SELF}:`) && g.includes('アサシン'));
        if (onPicked) {
          const notOnSource = !grants.some(g => g.startsWith(`${B41_OWNER_SOURCE}:`) && g.includes('アサシン'));
          const notOnOpponent = !grants.some(g => g.startsWith(`${B41_OWNER_OPP}:`))
            && !oppGrants.some(g => g.startsWith(`${B41_OWNER_OPP}:`));
          return {
            pass: notOnSource && notOnOpponent,
            detail: `ピッカー提示=${sawPicker} 候補=${JSON.stringify(candSnapshot)}／選んだ側に乗った=${onPicked}／効果元には乗らない=${notOnSource}／相手には乗らない=${notOnOpponent}（host grants=${JSON.stringify(grants)} guest grants=${JSON.stringify(oppGrants)}）`,
          };
        }
      }
      if (!did && st0?.turnPhase === 'MAIN') did = await H.clickBtn('アタックフェイズへ', { exact: true });
      // 選択後の確定＝「決定 (1/1)」。⚠ラベルに枚数が入るので `exact` は使えない（§4.4 罠2）＝
      //   `getByRole('button', {name})` の**前方一致**で拾う。
      if (!did && picked) did = await H.clickBtn('決定');
      if (!did) did = await H.clickTextOrBtn(['発動順序を確定', '確定', 'OK', 'はい']);
      if (!did && !energyPicked) {
        const energy = page.getByTestId('optcost-energy-0').first();
        if (await energy.count() && await energy.isVisible().catch(() => false)) {
          await energy.click().catch(() => {}); energyPicked = true; did = 'optcost-energy-0';
        }
      }
      if (!did && energyPicked && !paid) {
        const pay = page.getByTestId('optcost-pay').first();
        if (await pay.count() && await pay.isVisible().catch(() => false) && await pay.isEnabled().catch(() => false)) {
          await pay.click().catch(() => {}); paid = true; did = 'optcost-pay';
        }
      }
      const st = await H.queryState();
      H.log(`  b41owner[${s}] -> ${did ?? 'なし'} | phase=${st?.turnPhase} energyPicked=${energyPicked} paid=${paid} picked=${picked} pEff=${st?.pendingEffect ?? '-'} candidates=${JSON.stringify(st?.pendingCandidates)} grants=${JSON.stringify(st?.host?.keywordGrants)} energy=${JSON.stringify(st?.host?.energyCards)}`);
    }
    const fin = await H.queryState();
    return {
      pass: false,
      detail: `到達できず（energyPicked=${energyPicked} paid=${paid} sawPicker=${sawPicker} picked=${picked} pEff=${fin?.pendingEffect ?? '-'} candidates=${JSON.stringify(fin?.pendingCandidates)} grants=${JSON.stringify(fin?.host?.keywordGrants)}）`,
    };
  },
};

order.push('b41GrantKeywordExpiresAtTurnEnd', 'b41GrantKeywordTargetsOwnSigniOnly');
